INSERT INTO `crs_tabledata686` VALUES ('3', '{4241C22B-3BAE-463C-BA62-ECAA3A87C171}', '15', 'INHE-0450', '2015-12-30 16:21:25', '0000-00-00 00:00:00', '2015-12-30 16:21:25', 'unchecked', 'n', 'n', '', '1', '项目名称/立项申请', '', '客户名称', '客户编号', '百慕大', '姓名', '联系人电话', '联系人电邮', '客户背景', '项目名称', '项目类型', '阿尔及利亚', '项目合作条款/合作方式', '项目背景', '项目潜力', '投标截止日期', '样机需求数量', '项目来源国政治背景/社会经济状况', '订单操作的规范程度', '招标方（订单人）资信情况和合作态度（选填）', '项目要求的技术和商务资料的准备情况（选填）', '投标保函的开立情况', '个人意见', '行政人力资源部', '郭林鹏', '2015-12-30', '郭林鹏2015-12-30 16:21:25', '立项申请', 'lxdj2015123004', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1547', '{6241C22B-3BAE-463C-BA62-ECAA3A87A001}', '0', 'INHE-0015', '2012-05-08 15:46:12', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', '复活', null, 'Riddhi international Limited', '', '印度', '', 'Mahesh 00919953223542', '', '贸易公司，电子元器件进出口', '复活', '04', '印度', '我司提供代码预付费表及售电软件，客户开发485通讯控制器及软件本地化工作，主要面对印度小区物业管理市场，实现金额结算的双费率扣费（电网供电扣费和发电机供电扣费）预付费计量收费管理系统。', '印度预付费计量系统的主要用户是小区和物业管理单位，电力公司由于种种原因（主要是政策原因）还没有开始认可并使用预付费系统，此市场目前主要由印度当地的Secure公司占领，产品为非STS的代码预付费表，印度近几年经济增长迅速，房地产行业的增长率更高，每年都有大批的新房交付使用，而印度电力监管部门的政策已经放开二次计量市场（即电力公司可以采用总表收费、物业自营分表收费的方式对配电进行管理），在此政策下，不仅新房物业倾向于采用预付费计量方式，很多旧的小区也在进行相关的改造，因此，在未来的3-5年内，预付费计量系统', '50000只每年。', '', '', '', '', '', '', '', '此项目可以利用我们现有的产品用于推广，不会占用研发资源，主要的工作由客户来完成，又有一定的市场潜力，客户本身具备技术能力，可以很好的向潜在客户进行推广和推销，因此，建议立项，项目代号“复活”。', '国际业务一部', '王维', '2012-05-08', '王维 2012-05-08 15:46:12', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1548', '{6241C22B-3BAE-463C-BA62-ECAA3A87A002}', '0', 'INHE-0086', '2012-10-09 13:36:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'WIA', null, 'WiAIR PHILIPPINES,INC.', '', '菲律宾', '', '联系人： Edison Abella ( President)\r\n联系方式：eabella@wi-air.asia\r\n\r\n', '', '菲律宾市场老客户，在Ｄａｇｕｐａｎ电力公司以及菲当地ERC电监会有一定的关系，公司业务主要是通讯网络，电信服务等。', 'WIA', '04', '菲律宾', 'Dagupan电力公司AMR自动抄表试点项目，样机收费。\r\n\r\n客户项目实施计划安排：\r\n\r\n10月17号：要求我司完成1台GPRS圆表+1台DIN Rail PLC表+ 1台PLC预付费圆表（由于菲律宾ERC认证对表计的精度有严格要求，因此客户要求各款先准备3台样机，16号客户带回菲律宾，先做ERC测试和验证）\r\n\r\n10月25号：要求完成试点项目批量的15台GPRS圆表+2台DIN Rail PLC表+ 5台PLC预付费圆表。（如前面3台通过，后面的22台试点项目样机可顺利通过ERC认证，打上ERC铅', 'Ｄａｇｕｐａｎ镇约有３０万人口，Ｄａｇｕｐａｎ配电公司是一个私人电力公司，拥有７万用户，经营方式为购买电网供电并配送给用户，目前使用的电表主要是１００Ａ级别的单相三线表。现由于我司代理前期做的工作，该公司拟对计量系统进行升级，计划是分批将表计换成带ＡＭＲ功能的预付费后付费双模电表，在进行过公司及产品介绍后，该公司希望尽快进行１５－２０台规模的小批量试点，试点产品主要是带ＧＰＲＳ通讯的圆表及配套软件，要求为单相三线带ＧＰＲＳAMR功能的预付费后付费双模式电表，同时希望在进行试点的时候，可以同时试挂2只单相三', '', '', '', '', '', '', '', '', '', '国际业务一部', '王冉', '2012-10-09', '王冉 2012-10-09 14:43:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1549', '{6241C22B-3BAE-463C-BA62-ECAA3A87A003}', '0', 'INHE-0086', '2012-10-09 13:36:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'WIA', null, 'WiAIR PHILIPPINES,INC.', '', '菲律宾', '', '联系人： Edison Abella ( President)\r\n联系方式：eabella@wi-air.asia\r\n\r\n', '', '菲律宾市场老客户，在Ｄａｇｕｐａｎ电力公司以及菲当地ERC电监会有一定的关系，公司业务主要是通讯网络，电信服务等。', 'WIA', '04', '菲律宾', 'Dagupan电力公司AMR自动抄表试点项目，样机收费。\r\n\r\n客户项目实施计划安排：\r\n\r\n10月17号：要求我司完成1台GPRS圆表+1台DIN Rail PLC表+ 1台PLC预付费圆表（由于菲律宾ERC认证对表计的精度有严格要求，因此客户要求各款先准备3台样机，16号客户带回菲律宾，先做ERC测试和验证）\r\n\r\n10月25号：要求完成试点项目批量的15台GPRS圆表+2台DIN Rail PLC表+ 5台PLC预付费圆表。（如前面3台通过，后面的22台试点项目样机可顺利通过ERC认证，打上ERC铅', 'Ｄａｇｕｐａｎ镇约有３０万人口，Ｄａｇｕｐａｎ配电公司是一个私人电力公司，拥有７万用户，经营方式为购买电网供电并配送给用户，目前使用的电表主要是１００Ａ级别的单相三线表。现由于我司代理前期做的工作，该公司拟对计量系统进行升级，计划是分批将表计换成带ＡＭＲ功能的预付费后付费双模电表，在进行过公司及产品介绍后，该公司希望尽快进行１５－２０台规模的小批量试点，试点产品主要是带ＧＰＲＳ通讯的圆表及配套软件，要求为单相三线带ＧＰＲＳAMR功能的预付费后付费双模式电表，同时希望在进行试点的时候，可以同时试挂2只单相三', '', '', '', '', '', '', '', '', '', '国际业务一部', '王冉', '2012-10-09', '王冉 2012-10-09 14:43:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1550', '{6241C22B-3BAE-463C-BA62-ECAA3A87A004}', '0', 'INHE-0086', '2012-10-09 13:36:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'WIA', null, 'WiAIR PHILIPPINES,INC.', '', '菲律宾', '', '联系人： Edison Abella ( President)\r\n联系方式：eabella@wi-air.asia\r\n\r\n', '', '菲律宾市场老客户，在Ｄａｇｕｐａｎ电力公司以及菲当地ERC电监会有一定的关系，公司业务主要是通讯网络，电信服务等。', 'WIA', '04', '菲律宾', 'Dagupan电力公司AMR自动抄表试点项目，样机收费。\r\n\r\n客户项目实施计划安排：\r\n\r\n10月17号：要求我司完成1台GPRS圆表+1台DIN Rail PLC表+ 1台PLC预付费圆表（由于菲律宾ERC认证对表计的精度有严格要求，因此客户要求各款先准备3台样机，16号客户带回菲律宾，先做ERC测试和验证）\r\n\r\n10月25号：要求完成试点项目批量的15台GPRS圆表+2台DIN Rail PLC表+ 5台PLC预付费圆表。（如前面3台通过，后面的22台试点项目样机可顺利通过ERC认证，打上ERC铅', 'Ｄａｇｕｐａｎ镇约有３０万人口，Ｄａｇｕｐａｎ配电公司是一个私人电力公司，拥有７万用户，经营方式为购买电网供电并配送给用户，目前使用的电表主要是１００Ａ级别的单相三线表。现由于我司代理前期做的工作，该公司拟对计量系统进行升级，计划是分批将表计换成带ＡＭＲ功能的预付费后付费双模电表，在进行过公司及产品介绍后，该公司希望尽快进行１５－２０台规模的小批量试点，试点产品主要是带ＧＰＲＳ通讯的圆表及配套软件，要求为单相三线带ＧＰＲＳAMR功能的预付费后付费双模式电表，同时希望在进行试点的时候，可以同时试挂2只单相三', '', '', '', '', '', '', '', '', '', '国际业务一部', '王冉', '2012-10-09', '王冉 2012-10-09 14:43:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1551', '{6241C22B-3BAE-463C-BA62-ECAA3A87A005}', '0', 'INHE-0086', '2012-10-09 13:36:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'WIA', null, 'WiAIR PHILIPPINES,INC.', '', '菲律宾', '', '联系人： Edison Abella ( President)\r\n联系方式：eabella@wi-air.asia\r\n\r\n', '', '菲律宾市场老客户，在Ｄａｇｕｐａｎ电力公司以及菲当地ERC电监会有一定的关系，公司业务主要是通讯网络，电信服务等。', 'WIA', '04', '菲律宾', 'Dagupan电力公司AMR自动抄表试点项目，样机收费。\r\n\r\n客户项目实施计划安排：\r\n\r\n10月17号：要求我司完成1台GPRS圆表+1台DIN Rail PLC表+ 1台PLC预付费圆表（由于菲律宾ERC认证对表计的精度有严格要求，因此客户要求各款先准备3台样机，16号客户带回菲律宾，先做ERC测试和验证）\r\n\r\n10月25号：要求完成试点项目批量的15台GPRS圆表+2台DIN Rail PLC表+ 5台PLC预付费圆表。（如前面3台通过，后面的22台试点项目样机可顺利通过ERC认证，打上ERC铅', 'Ｄａｇｕｐａｎ镇约有３０万人口，Ｄａｇｕｐａｎ配电公司是一个私人电力公司，拥有７万用户，经营方式为购买电网供电并配送给用户，目前使用的电表主要是１００Ａ级别的单相三线表。现由于我司代理前期做的工作，该公司拟对计量系统进行升级，计划是分批将表计换成带ＡＭＲ功能的预付费后付费双模电表，在进行过公司及产品介绍后，该公司希望尽快进行１５－２０台规模的小批量试点，试点产品主要是带ＧＰＲＳ通讯的圆表及配套软件，要求为单相三线带ＧＰＲＳAMR功能的预付费后付费双模式电表，同时希望在进行试点的时候，可以同时试挂2只单相三', '', '', '', '', '', '', '', '', '', '国际业务一部', '王冉', '2012-10-09', '王冉 2012-10-09 14:43:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1552', '{6241C22B-3BAE-463C-BA62-ECAA3A87A006}', '0', 'INHE-0086', '2012-10-09 13:36:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'WIA', null, 'WiAIR PHILIPPINES,INC.', '', '菲律宾', '', '联系人： Edison Abella ( President)\r\n联系方式：eabella@wi-air.asia\r\n\r\n', '', '菲律宾市场老客户，在Ｄａｇｕｐａｎ电力公司以及菲当地ERC电监会有一定的关系，公司业务主要是通讯网络，电信服务等。', 'WIA', '04', '菲律宾', 'Dagupan电力公司AMR自动抄表试点项目，样机收费。\r\n\r\n客户项目实施计划安排：\r\n\r\n10月17号：要求我司完成1台GPRS圆表+1台DIN Rail PLC表+ 1台PLC预付费圆表（由于菲律宾ERC认证对表计的精度有严格要求，因此客户要求各款先准备3台样机，16号客户带回菲律宾，先做ERC测试和验证）\r\n\r\n10月25号：要求完成试点项目批量的15台GPRS圆表+2台DIN Rail PLC表+ 5台PLC预付费圆表。（如前面3台通过，后面的22台试点项目样机可顺利通过ERC认证，打上ERC铅', 'Ｄａｇｕｐａｎ镇约有３０万人口，Ｄａｇｕｐａｎ配电公司是一个私人电力公司，拥有７万用户，经营方式为购买电网供电并配送给用户，目前使用的电表主要是１００Ａ级别的单相三线表。现由于我司代理前期做的工作，该公司拟对计量系统进行升级，计划是分批将表计换成带ＡＭＲ功能的预付费后付费双模电表，在进行过公司及产品介绍后，该公司希望尽快进行１５－２０台规模的小批量试点，试点产品主要是带ＧＰＲＳ通讯的圆表及配套软件，要求为单相三线带ＧＰＲＳAMR功能的预付费后付费双模式电表，同时希望在进行试点的时候，可以同时试挂2只单相三', '', '', '', '', '', '', '', '', '', '国际业务一部', '王冉', '2012-10-09', '王冉 2012-10-09 14:43:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1553', '{6241C22B-3BAE-463C-BA62-ECAA3A87A007}', '0', 'INHE-0091', '2012-07-24 17:22:07', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'HET', null, 'Harnessing Environmental Technologies Ltd.', '', '毛里求斯', '', 'Managing Director：Dr Jimmy Leblanc\r\nhet-jleblanc@orange.mu\r\nTel: +230 433 3155\r\n', '', '该客户是以下知名品牌在印度洋地区的代理：SIEMENS，DAIKIN，DINEL，K-FLEX，TEEO ', 'HET', '04', '毛里求斯', '我司供货给客户，客户再将电表卖给其客户。', '客户想成为银河表计在印度洋地区的代理，目前收到一家商业中心物主关于预付费代码表的咨询；客户想通过样机的成功测试使用拿下订单。', '样机将安装在商业中心，进行使用测试。测试成功，有50至100台的订单。此商业中心将是客户推广银河表计产品的展示地。后期推动客户到电力公司进行推广。', '', '', '', '', '', '', '', '', '国际业务二部', '林丽璇(Elle Lin)', '2012-07-26', '林丽璇 2012-07-26 09:08:18', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
