INSERT INTO `crs_tabledata686` VALUES ('1556', '{6241C22B-3BAE-463C-BA62-ECAA3A87A010}', '0', 'INHE-0051', '2012-09-07 09:32:43', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'CEB5', null, 'Harnessing Environmental Technologies Ltd.', '', '毛里求斯', '', 'Managing Director：Dr Jimmy Leblanc \nhet-jleblanc@orange.mu \nTel: +230 433 3155', '', '该客户是以下知名品牌在印度洋地区的代理：SIEMENS，DAIKIN，DINEL，K-FLEX，TEEO.主要提供节能方案和产品，包括供暖，通风，空调等产品。\n', 'CEB5', '04', '毛里求斯', '以代理公司名义投标，银河做为厂家支持。', '此标是毛里求斯电力公司CEB发布的，CEB自筹资金。毛里求斯目前还未批量使用预付费电表，也无预付费招标项目。', '参加投标，考察代理实力，宣传银河品牌产品，为后期推进预付费产品做准备。', '2012年10月3日', '1台', '毛里求斯是非洲经济发展较好的国家之一，外贸是毛国民经济的重要组成部分。主要出口蔗糖和出口加工区产品，进口粮食及其他食品、棉毛原料、机器设备、石油产品等。', '良好', '', '见附件投标资料列表', '', '1.技术部分按照评分制，投标报价*总分18分/实际得分=评标价格\r\n2.竞争对手主要为兰吉尔，EDMI，ELSTER和ISKRAEMECO,去年招标项目中标方为ISKRAEMECO.银河第一次参加此国家招标项目，只要产品满足要求，价格应该比这些国外公司有优势。\r\n', '国际业务二部', '盛燕', '2012-09-07', '盛燕 2012-09-07 09:32:43', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
