INSERT INTO `crs_tabledata686` VALUES ('1560', '{6241C22B-3BAE-463C-BA62-ECAA3A87A014}', '0', 'INHE-0086', '2012-09-06 09:53:27', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'MAD', null, 'Plankton Investment Pvt Ltd', '', '马尔代夫', '', '客户名称：Athif (Mr)\r\n联系方式：fax. +9603313678，Mob. +9607773514\r\nEmail:info@theplankton.biz', '', '客户Plankton Investment Pvt Ltd公司，主要产品是建筑配电板.发电站发电机板和安装，以及其他电力设备和配件，客户在当地马尔代夫市场也销售过Fujidharuma的表，该市场现主要使用的还是转盘式机械表和机电一体式机械表。', 'MAD', '03', '马尔代夫', '客户支付样机费用，如测试和认证通过，客户将在当地市场和电力公司运作和推广电子式电表，从而进行批量直接采购或者推动招投标采购.', '客户现有意向购买5台单相电子式电表和5台三相表用于马尔代夫State Electric Company Limited (STELCO)测试和认证，如测试通过客户可考虑批量购买和在当地市场以及电力公司推广电子式电表。', '', '', '', '', '', '', '', '', '', '国际业务一部', '王冉', '2012-09-06', '王冉 2012-09-06 10:05:32', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
