INSERT INTO `crs_tabledata686` VALUES ('1616', '{6241C22B-3BAE-463C-BA62-ECAA3A87A070}', '0', 'JXINHE-2433', '2015-11-12 10:59:36', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YI', null, 'Meezh Trading Co.', '', '约旦', '', 'Mohammad Madi/ Meezah Trading Co. /mmadi@meezah.com/ Tel.  +962 6 461 0040 /Mob +962 79 599 9155　　', '', '代理公司是一家贸易公司，成立于2000年，员工数5-10人。做过转换器，电线，开关柜，绝缘子和断路器等。代理公司的年销售量为800-1000万美金（包括各种产品）。代理的祖父是JEPCO电力公司的奠基人，是董事会的成员，代理的哥哥也在JEPCO电力公司工作。', 'YI', '03', '约旦', '我司直接参与投标，代理后续跟进，拿5%的佣金。　　', '约旦电力公司IDECO招标项目　　', '', '2015年12月9日', '1台电表样机和1台带无线探头的HHU', '政局相对稳定，人口数量约646万人，人均GDP 5,021美元　　', '相对规范，主要靠产品的质量，技术要求和产品的价格　', '', '', '5%投标保函，10%履约保函。我司开保函直接参与投标，代理后续跟进，拿5%的佣金。　', '项目代号：YI', '国际业务三部', '黄倩', '2015-11-25', '黄倩 2015-11-25 10:32:31', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
