INSERT INTO `crs_tabledata686` VALUES ('1629', '{6241C22B-3BAE-463C-BA62-ECAA3A87A083}', '0', 'INHE-0399', '2015-06-24 11:19:55', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'MAS', null, 'Energy Solution Provider', '', '马来西亚', '', 'Philip Gan General Manager\r\n+6012 210 9188\r\npgan@esp.my', '', '马来西亚做电力节能方面的一家公司，也做电表，10年前就做过机械电表。1年前就开始运作现在这个项目，最早和龙五星交流过。', 'MAS', '04', '马来西亚', '直接采购供货。支付方式T/T或者L/C，我司决定。', '', '首订单在100,000 只。如果表功能符合要求，第二个订单在500,000只。最快9月份能够有订单发来。', '', '客户下样机订单', '', '', '', '', '', '合作方直接采购然后卖给电力公司，数量较可观，时间快，回款快。可以开展合作。客户称电力公司计划在5年内采购800万只表，只有3家公司来竞争。客户计划拿到200万只的订单。', '国际业务一部', '左三维 ', '2015-08-07', '左三维 2015-08-07 15:33:33', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1630', '{6241C22B-3BAE-463C-BA62-ECAA3A87A084}', '0', 'INHE-0399', '2015-06-24 11:19:55', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'MAS', null, 'Energy Solution Provider', '', '马来西亚', '', 'Philip Gan General Manager\r\n+6012 210 9188\r\npgan@esp.my', '', '马来西亚做电力节能方面的一家公司，也做电表，10年前就做过机械电表。1年前就开始运作现在这个项目，最早和龙五星交流过。', 'MAS', '04', '马来西亚', '直接采购供货。支付方式T/T或者L/C，我司决定。', '', '首订单在100,000 只。如果表功能符合要求，第二个订单在500,000只。最快9月份能够有订单发来。', '', '客户下样机订单', '', '', '', '', '', '合作方直接采购然后卖给电力公司，数量较可观，时间快，回款快。可以开展合作。客户称电力公司计划在5年内采购800万只表，只有3家公司来竞争。客户计划拿到200万只的订单。', '国际业务一部', '左三维 ', '2015-08-07', '左三维 2015-08-07 15:33:33', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1631', '{6241C22B-3BAE-463C-BA62-ECAA3A87A085}', '0', 'INHE-0408', '2015-04-13 09:35:46', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'DS50', null, 'GLOBAL ENERGY SYSTEM SARL', '', '摩洛哥', '', 'Président Directeur Général Dalaa Mohamed Mustapha Siège social : 13, Angle Rue de l \'Esparre et Bd, la Gironde 5eme Etage appt : 18&#8226; - Casablanca - Tel  :  00212 5 22 30 15 67 - Fax :   00212 5 22 30 15 80 GSM: +(212) 6 61 23 65 57 Email:m.mustapha', '', '摩洛哥本地电力设备供应商，与马达加斯加电力公司商业部经理有较好的个人关系。', 'DS50', '', '马达加斯加', '我司独立提交意向函，代理负责与电力公司的沟通及公关工作', '马达加斯加国家电力公司拥有50万客户，目前面临最大问题是收益安全和用户窃电问题，希望通过引入资深的合作伙伴，在技术层面上灵活运用预付费/后付费切换以及集抄控制，来解决窃电问题，保障收益安全，减少国家财政援助。\r\n目前该国电力公司发出公开意向征询函件（资格预审），希望参与者提供技术方案、经验介绍、成功案例以及融资方案和商业计划。\r\n预计需要50万台电表。', '', '2015年4月20日', '0', '稳定', '', '', '', '暂不涉及保函。', '项目代号：DS50', '国际业务一部', '郑丽莎 ', '2015-04-13', '郑丽莎 2015-04-13 09:39:39', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1632', '{6241C22B-3BAE-463C-BA62-ECAA3A87A086}', '0', 'INHE-0424', '2015-07-08 09:04:44', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'KM', null, 'KAMA.SA', '', '马里', '', 'Neneman CAMARA\r\nCell : 00 223 66 75 59 22\r\nL.D : 00 223 20 23 03 13/15\r\nTel  : 00 223 20 23 03 32\r\n        00 223 20 23 03 33\r\nFax : 00 223 20 23 03 05\r\nEmail : ncamara@kama-sa.com\r\nWeb site : www.kama-sa.com', '', 'KAMA SA是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。该公司通过和马里政府2003年引进的公共、私营合作伙伴合作实施农村电气化项目，迄今为止该公司已经通电（实现电网，电厂建设，设备组）19个地区，覆盖约10万居民，给约4471用户提供电力。已实现发电机总功率3647千伏安的供应和12公里中压网; 148公里的低压电网建设。\r\n\r\n', 'KM', '04', '马里', '直接采购 \r\n全额预付T/T　\r\n', '该公司通过和马里政府合作实施农村电气化项目需要用到我司电表。', '市场需求大', '', '', '', '', '', '', '', '客户急需报价，如价格ok可直接洽谈下单事宜。请公司同意立项。\r\n\r\n项目代号KM。\r\n', '国际业务一部', '代莎', '2015-07-08', '代莎 2015-07-08 09:04:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1633', '{6241C22B-3BAE-463C-BA62-ECAA3A87A087}', '0', 'INHE-0424', '2015-07-08 09:04:44', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'KM', null, 'KAMA.SA', '', '马里', '', 'Neneman CAMARA\r\nCell : 00 223 66 75 59 22\r\nL.D : 00 223 20 23 03 13/15\r\nTel  : 00 223 20 23 03 32\r\n        00 223 20 23 03 33\r\nFax : 00 223 20 23 03 05\r\nEmail : ncamara@kama-sa.com\r\nWeb site : www.kama-sa.com', '', 'KAMA SA是一家私营公司，经营的领域甚广，包括：进口，销售和出口电、气、材料和设备。该公司通过和马里政府2003年引进的公共、私营合作伙伴合作实施农村电气化项目，迄今为止该公司已经通电（实现电网，电厂建设，设备组）19个地区，覆盖约10万居民，给约4471用户提供电力。已实现发电机总功率3647千伏安的供应和12公里中压网; 148公里的低压电网建设。\r\n\r\n', 'KM', '04', '马里', '直接采购 \r\n全额预付T/T　\r\n', '该公司通过和马里政府合作实施农村电气化项目需要用到我司电表。', '市场需求大', '', '', '', '', '', '', '', '客户急需报价，如价格ok可直接洽谈下单事宜。请公司同意立项。\r\n\r\n项目代号KM。\r\n', '国际业务一部', '代莎', '2015-07-08', '代莎 2015-07-08 09:04:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1634', '{6241C22B-3BAE-463C-BA62-ECAA3A87A088}', '0', 'INHE-0391', '2015-06-29 14:54:45', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'ZAR', null, 'Makgaji Printing and Projects T/A Makgaji Projects and Consulting Close Corporation', '', '南非', '', 'Mmatholo Mabotja(Managing Director)\n\nTel: 012 361 0012\nCell: 081 748 2105', '', 'Makgji公司已中Lekwa市政府的25，000台和系统的标，该公司为市政府提供电力服务，帮电力公司管理售电系统，联系银河提供电表和系统。', 'ZAR', '04', '南非', '直接采购', 'Makgji公司已中Lekwa市政府的25，000台和系统的标，该公司为市政府提供电力服务，帮电力公司管理售电系统，联系银河提供电表和系统。25，000台电表分5批进行生产，本来要以融资模式进行，经协商，已改为直接采购。', '目前25，000台的项目一旦成功，根据南非法律，无需投标可直接复制到南非其他市政府类似项目，形成后续订单。', '', '', '南非后付费电表较多，多出现窃电现象，地方政府电费收入流失严重，由于市政府只负责配电，ESKOM电力公司向市政府供电，因此很多市政府无法及时支付ESKOM供电费用，导致ESKOM电力公司想暂停供电，国家政府为防止此现象发生，要求全国逐步更换掉后付费电表，使用预付费电表。\r\n\r\n南非经济相比于其他非洲国家要先进很多，道路设施发达，大多数人都有车可开，未来电表市场潜力很大。', '', 'Makgaji的常务董事总经理Mmatholo女士之前在兰吉尔工作数年，对电表市场了解深刻，关于项目细节，我们经过多次商讨，其态度认真，真诚想与银河就本项目获得成功，以求未来长远合作。', '合同已经签订，技术资料等Makgaji公司明确，一旦收到预付款，即可进行生产。', '', '该项目可能是打开南非市场的开门砖，因为南非电表市场潜力很大。但要真正进入该市场，注册当地公司才能真正参与竞争。', '国际业务一部', '桂弯弯 ', '2015-06-29', '桂弯弯 2015-06-29 14:54:54', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1635', '{6241C22B-3BAE-463C-BA62-ECAA3A87A089}', '0', 'INHE-0391', '2015-06-29 14:54:45', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'ZAR', null, 'Makgaji Printing and Projects T/A Makgaji Projects and Consulting Close Corporation', '', '南非', '', 'Mmatholo Mabotja(Managing Director)\n\nTel: 012 361 0012\nCell: 081 748 2105', '', 'Makgji公司已中Lekwa市政府的25，000台和系统的标，该公司为市政府提供电力服务，帮电力公司管理售电系统，联系银河提供电表和系统。', 'ZAR', '04', '南非', '直接采购', 'Makgji公司已中Lekwa市政府的25，000台和系统的标，该公司为市政府提供电力服务，帮电力公司管理售电系统，联系银河提供电表和系统。25，000台电表分5批进行生产，本来要以融资模式进行，经协商，已改为直接采购。', '目前25，000台的项目一旦成功，根据南非法律，无需投标可直接复制到南非其他市政府类似项目，形成后续订单。', '', '', '南非后付费电表较多，多出现窃电现象，地方政府电费收入流失严重，由于市政府只负责配电，ESKOM电力公司向市政府供电，因此很多市政府无法及时支付ESKOM供电费用，导致ESKOM电力公司想暂停供电，国家政府为防止此现象发生，要求全国逐步更换掉后付费电表，使用预付费电表。\r\n\r\n南非经济相比于其他非洲国家要先进很多，道路设施发达，大多数人都有车可开，未来电表市场潜力很大。', '', 'Makgaji的常务董事总经理Mmatholo女士之前在兰吉尔工作数年，对电表市场了解深刻，关于项目细节，我们经过多次商讨，其态度认真，真诚想与银河就本项目获得成功，以求未来长远合作。', '合同已经签订，技术资料等Makgaji公司明确，一旦收到预付款，即可进行生产。', '', '该项目可能是打开南非市场的开门砖，因为南非电表市场潜力很大。但要真正进入该市场，注册当地公司才能真正参与竞争。', '国际业务一部', '桂弯弯 ', '2015-06-29', '桂弯弯 2015-06-29 14:54:54', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1636', '{6241C22B-3BAE-463C-BA62-ECAA3A87A090}', '0', 'INHE-0391', '2015-06-29 14:54:45', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'ZAR', null, 'Makgaji Printing and Projects T/A Makgaji Projects and Consulting Close Corporation', '', '南非', '', 'Mmatholo Mabotja(Managing Director)\n\nTel: 012 361 0012\nCell: 081 748 2105', '', 'Makgji公司已中Lekwa市政府的25，000台和系统的标，该公司为市政府提供电力服务，帮电力公司管理售电系统，联系银河提供电表和系统。', 'ZAR', '04', '南非', '直接采购', 'Makgji公司已中Lekwa市政府的25，000台和系统的标，该公司为市政府提供电力服务，帮电力公司管理售电系统，联系银河提供电表和系统。25，000台电表分5批进行生产，本来要以融资模式进行，经协商，已改为直接采购。', '目前25，000台的项目一旦成功，根据南非法律，无需投标可直接复制到南非其他市政府类似项目，形成后续订单。', '', '', '南非后付费电表较多，多出现窃电现象，地方政府电费收入流失严重，由于市政府只负责配电，ESKOM电力公司向市政府供电，因此很多市政府无法及时支付ESKOM供电费用，导致ESKOM电力公司想暂停供电，国家政府为防止此现象发生，要求全国逐步更换掉后付费电表，使用预付费电表。\r\n\r\n南非经济相比于其他非洲国家要先进很多，道路设施发达，大多数人都有车可开，未来电表市场潜力很大。', '', 'Makgaji的常务董事总经理Mmatholo女士之前在兰吉尔工作数年，对电表市场了解深刻，关于项目细节，我们经过多次商讨，其态度认真，真诚想与银河就本项目获得成功，以求未来长远合作。', '合同已经签订，技术资料等Makgaji公司明确，一旦收到预付款，即可进行生产。', '', '该项目可能是打开南非市场的开门砖，因为南非电表市场潜力很大。但要真正进入该市场，注册当地公司才能真正参与竞争。', '国际业务一部', '桂弯弯 ', '2015-06-29', '桂弯弯 2015-06-29 14:54:54', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1637', '{6241C22B-3BAE-463C-BA62-ECAA3A87A091}', '0', 'INHE-0391', '2015-07-22 16:55:22', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'TWN', null, 'Makgaji Printing and Projects T/A Makgaji Projects and Consulting Close Corporation', '', '南非', '', 'Mmatholo Mabotja(Managing Director)\n\nTel: 012 361 0012\nCell: 081 748 2105', '', '茨瓦内市政府之前有过30万台电表的招标项目，Conlic公司中标，但该项目的电表品牌由市政府的一位名叫Jim的工程师经理指定，海兴给Jim每台表1美金的佣金，因此海兴已向茨瓦内供货25万台。现在该市政府有3万台的项目，我们打算向Jim提供两台银河电表样机测试且予以每台表2美金左右的佣金，让其指定银河电表品牌为供应商品牌，获得该3万台项目。\r\n\r\n 除此之外，茨瓦内市政府7月底或八月初有80万台的招标项目，如果该3万台能拿到，有利于我们与茨瓦内市政府建立关系，有助于我们银河拿下该80万招标项目。', 'TWN', '04', '南非', '\r\n\r\n10%的预付款，发货前收到剩下的90%货款。', '茨瓦内市政府之前有过30万台电表的招标项目，Conlic公司中标，但该项目的电表品牌由市政府的一位名叫Jim的工程师经理指定，海兴给Jim每台表1美金的佣金，因此海兴已向茨瓦内供货25万台。现在该市政府有3万台的项目，我们打算向Jim提供两台银河电表样机测试且予以每台表2美金左右的佣金，让其指定银河电表品牌为供应商品牌，获得该3万台项目。\r\n\r\n 除此之外，茨瓦内市政府7月底或八月初有80万台的招标项目，如果该3万台能拿到，有利于我们与茨瓦内市政府建立关系，有助于我们银河拿下该80万招标项目。', '\r\n\r\n有助于拿下80万台茨瓦内项目', '', '', '', '', '', '', '', '\r\n先将样机提供给茨瓦内市政府的工程师，与他建立良好关系后，争取市政府的支持。', '国际业务一部', '桂弯弯 ', '2015-07-22', '桂弯弯 2015-07-22 16:55:22', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1638', '{6241C22B-3BAE-463C-BA62-ECAA3A87A092}', '0', 'INHE-0354', '2015-01-09 09:52:11', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', '水电', null, '湖州众益物资贸易有限公司', '', '中国', '', '联系人：高兴\n联系电话：0086-15905726372　', '', '水利水电是此项目承包商，湖州众益物资贸易有限公司为此项目的采购商，合同的签订及付款均由众益负责和安排。', '水电', '04', '安哥拉', '客户直接采购 ', '项目已中标，急需采购电表，交期较为紧急。', '', '', '', '', '', '', '', '', '', '国际业务二部', '罗银凤 ', '2015-01-09', '罗银凤 2015-01-09 10:32:04', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
