INSERT INTO `crs_tabledata686` VALUES ('1650', '{6241C22B-3BAE-463C-BA62-ECAA3A87A104}', '0', 'INHE-0486', '2015-12-08 11:24:15', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'C3', null, 'Kabelek Engineering Ltd', '', '毛里求斯', '', 'Name:Karen\r\nPosition:Purchase Manager\r\nEmail:kabelek@intnet.mu\r\nTel : (230) 212 4826', '', '成立于2007年在毛里求斯注册提供一系列全套的电力和机械工程服务。电线安装测试，工业建筑电力安装，管道安装，民用和商用的自动化建设，再生性能源系统建设。', 'C3', '03', '毛里求斯', '代理投标', '毛里求斯CEB采购电表来扩展其智能电网系统。该项目交货方式为DAP或DDP，付款方式为交货后30天内凭发票和相关文件付款。此前银河有和当地代理合作投过相关电表项目，但是由于产品证书原因未能中标。', '', '2016年1月20日', '每种电表及模块各一个', '毛里求斯是非洲经济发展较好国家。在世界经济论坛2014—2015年“全球竞争力排名”中，毛排名全球第39位，在撒哈拉以南非洲名列首位，是非洲三个人类发展指数被评为“高”级别的国家之一。', '从其招标文件来看，此次招标符合国际招投标的相关规定。', '', '', '只需要投标保证声明，不需要开立投标保函', '银河之前投过毛里求斯相关电表项目，且有代理主动联系投标。此项目主要关键在于产品技术规格需满足招标方要求。', '国际业务二部', '吴欢', '2015-12-08', '吴欢 2015-12-08 11:24:16', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1651', '{6241C22B-3BAE-463C-BA62-ECAA3A87A105}', '0', 'INHE-0486', '2015-12-08 11:24:15', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'C3', null, 'Kabelek Engineering Ltd', '', '毛里求斯', '', 'Name:Karen\r\nPosition:Purchase Manager\r\nEmail:kabelek@intnet.mu\r\nTel : (230) 212 4826', '', '成立于2007年在毛里求斯注册提供一系列全套的电力和机械工程服务。电线安装测试，工业建筑电力安装，管道安装，民用和商用的自动化建设，再生性能源系统建设。', 'C3', '03', '毛里求斯', '代理投标', '毛里求斯CEB采购电表来扩展其智能电网系统。该项目交货方式为DAP或DDP，付款方式为交货后30天内凭发票和相关文件付款。此前银河有和当地代理合作投过相关电表项目，但是由于产品证书原因未能中标。', '', '2016年1月20日', '每种电表及模块各一个', '毛里求斯是非洲经济发展较好国家。在世界经济论坛2014—2015年“全球竞争力排名”中，毛排名全球第39位，在撒哈拉以南非洲名列首位，是非洲三个人类发展指数被评为“高”级别的国家之一。', '从其招标文件来看，此次招标符合国际招投标的相关规定。', '', '', '只需要投标保证声明，不需要开立投标保函', '银河之前投过毛里求斯相关电表项目，且有代理主动联系投标。此项目主要关键在于产品技术规格需满足招标方要求。', '国际业务二部', '吴欢', '2015-12-08', '吴欢 2015-12-08 11:24:16', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
