INSERT INTO `crs_tabledata686` VALUES ('1671', '{6241C22B-3BAE-463C-BA62-ECAA3A87A125}', '0', 'INHE-0486', '2015-11-21 09:54:31', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'EW10', null, 'Tripplesea Limited', '', '尼日利亚', '', 'Ebube Chukwujekwu\r\nPhone: +234-805-641-6008   +234-703-327-8516\r\nEmail: ebube.chukwujekwu@trippleseagroup.com', '', '- 性质：私人企业，1999年成立          \r\n- 主要经营项目：1）电子产品及高压电力解决方案，其中UPS有自己的品牌Blue Gate,家喻户晓，且占有尼日利亚65%的市场额。2）通讯信息技术类硬件产品如电脑零部件，LCD监控器等。3）动物药类及食品供应。\r\n- 已与银河合作的联合投标项目：NP01。含电表，表箱，系统，安装等。去年已执行完毕。', 'EW10', '03', '卢旺达', '\r\n\r\n还未决定投标方式', '在2015年11月份，卢旺达政府正式决定使用一部分来自国际开发协会的贷款来进行当地的EASSDP项目，该项目旨在为当地居民和企业提供可靠和实惠的电力供应。因此，卢旺达能源发展有限公司进行了此次电表招标项目。\r\n该项目价格条款为CIP，付款方式为10% advance payment，80% on delivery, 10% on \r\nacceptance.', '', '2015年12月22日', '无样机需求', '\r\n卢旺达是非洲中东部国家，首都为基加利，总人口1180万。近年来，卢政府积极开展良政建设，促进经济发展，缓和社会矛盾，卢政局保持稳定。卢旺达是联合国公布的世界最不发达国家之一。经济以农牧业为主，粮食不能自给。\r\n', '\r\n\r\n根据招标文件来看，此次招标程序符合国际招投标标准。', '', '', '\r\n\r\n还未开立投标保函', '卢旺达近些年对智能电表需求较大，且公司此前投过该市场项目，熟悉该市场，因此此次投标是可行的。', '国际业务二部', '吴欢', '2015-11-21', '吴欢 2015-11-21 14:45:59', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1672', '{6241C22B-3BAE-463C-BA62-ECAA3A87A126}', '0', 'INHE-0486', '2015-11-21 09:54:31', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'EW10', null, 'Tripplesea Limited', '', '尼日利亚', '', 'Ebube Chukwujekwu\r\nPhone: +234-805-641-6008   +234-703-327-8516\r\nEmail: ebube.chukwujekwu@trippleseagroup.com', '', '- 性质：私人企业，1999年成立          \r\n- 主要经营项目：1）电子产品及高压电力解决方案，其中UPS有自己的品牌Blue Gate,家喻户晓，且占有尼日利亚65%的市场额。2）通讯信息技术类硬件产品如电脑零部件，LCD监控器等。3）动物药类及食品供应。\r\n- 已与银河合作的联合投标项目：NP01。含电表，表箱，系统，安装等。去年已执行完毕。', 'EW10', '03', '卢旺达', '\r\n\r\n还未决定投标方式', '在2015年11月份，卢旺达政府正式决定使用一部分来自国际开发协会的贷款来进行当地的EASSDP项目，该项目旨在为当地居民和企业提供可靠和实惠的电力供应。因此，卢旺达能源发展有限公司进行了此次电表招标项目。\r\n该项目价格条款为CIP，付款方式为10% advance payment，80% on delivery, 10% on \r\nacceptance.', '', '2015年12月22日', '无样机需求', '\r\n卢旺达是非洲中东部国家，首都为基加利，总人口1180万。近年来，卢政府积极开展良政建设，促进经济发展，缓和社会矛盾，卢政局保持稳定。卢旺达是联合国公布的世界最不发达国家之一。经济以农牧业为主，粮食不能自给。\r\n', '\r\n\r\n根据招标文件来看，此次招标程序符合国际招投标标准。', '', '', '\r\n\r\n还未开立投标保函', '卢旺达近些年对智能电表需求较大，且公司此前投过该市场项目，熟悉该市场，因此此次投标是可行的。', '国际业务二部', '吴欢', '2015-11-21', '吴欢 2015-11-21 14:45:59', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1673', '{6241C22B-3BAE-463C-BA62-ECAA3A87A127}', '0', 'INHE-0486', '2015-11-21 09:54:31', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'EW10', null, 'Tripplesea Limited', '', '尼日利亚', '', 'Ebube Chukwujekwu\r\nPhone: +234-805-641-6008   +234-703-327-8516\r\nEmail: ebube.chukwujekwu@trippleseagroup.com', '', '- 性质：私人企业，1999年成立          \r\n- 主要经营项目：1）电子产品及高压电力解决方案，其中UPS有自己的品牌Blue Gate,家喻户晓，且占有尼日利亚65%的市场额。2）通讯信息技术类硬件产品如电脑零部件，LCD监控器等。3）动物药类及食品供应。\r\n- 已与银河合作的联合投标项目：NP01。含电表，表箱，系统，安装等。去年已执行完毕。', 'EW10', '03', '卢旺达', '\r\n\r\n还未决定投标方式', '在2015年11月份，卢旺达政府正式决定使用一部分来自国际开发协会的贷款来进行当地的EASSDP项目，该项目旨在为当地居民和企业提供可靠和实惠的电力供应。因此，卢旺达能源发展有限公司进行了此次电表招标项目。\r\n该项目价格条款为CIP，付款方式为10% advance payment，80% on delivery, 10% on \r\nacceptance.', '', '2015年12月22日', '无样机需求', '\r\n卢旺达是非洲中东部国家，首都为基加利，总人口1180万。近年来，卢政府积极开展良政建设，促进经济发展，缓和社会矛盾，卢政局保持稳定。卢旺达是联合国公布的世界最不发达国家之一。经济以农牧业为主，粮食不能自给。\r\n', '\r\n\r\n根据招标文件来看，此次招标程序符合国际招投标标准。', '', '', '\r\n\r\n还未开立投标保函', '卢旺达近些年对智能电表需求较大，且公司此前投过该市场项目，熟悉该市场，因此此次投标是可行的。', '国际业务二部', '吴欢', '2015-11-21', '吴欢 2015-11-21 14:45:59', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1674', '{6241C22B-3BAE-463C-BA62-ECAA3A87A128}', '0', 'INHE-0393', '2015-11-05 16:38:03', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'MP8', null, 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', '', '马拉维', '', '姓名：Khumbolawo Lungu.\r\n职位：马拉维能源部采购\r\n邮箱：khumbolungu@gmail\r\n手机：+265 999922356\r\n座机：+265 1 770 688	', '', '能源部2013年有一个类似的招标，当时银河投标了，最终CONLOG中标。', 'MP8', '03', '马拉维', '银河直接投标。', '马拉维能源部的乡村电气化计划第八阶段招标。', '', '2015年11月25日', '0', '政治较稳定，社会经济相对于非洲其他国家状况一般。', '订单操作较规范。', '', '', '须开立投标保函，保函金额为投标报价的1%。', '市场成熟，我们借此机会向能源部推广银河，推广DINiii。此项目为能源部乡村电气化工程的第8阶段招标，应该还会有后续订单。', '国际业务二部', '李新国 ', '2015-11-05', '李新国 2015-11-05 17:22:29', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
