INSERT INTO `crs_tabledata686` VALUES ('1729', '{6241C22B-3BAE-463C-BA62-ECAA3A87A183}', '0', 'INHE-0222', '2015-12-05 22:31:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'FIX', null, 'FIX-IT Depot ', '', '圭亚那', '', 'Paul James: pjames1000@hotmail.com\r\nTel: 00592 600 6066', '', '五金产品及电力产品经销商，在电力公司有较广人脉，精通商务运作。', 'FIX', '03', '圭亚那', '代理作为总包商直接投标，我司提供电表及表箱相关样机及文件等支持投标。', '此为圭亚那国家电力公司GPL输电变电线路改造大型交钥匙工程，产品含整个电网改造过程中所需各种设备，变压器，电线杆，线材，电表，表箱，工具，五金配件等，电表只占其中一部分。', '为未来AMI项目做储备，成功中标有利于后续AMI项目进一步运作及参与。', '42388', '每款1台', '', '规范', '良好', '最终版技术规格确认，投标资料准备中。', '代理开立投标保函', '1.请公司尽快评估100A单相3线可更换模块智能电表实现方案（RF+PLC通讯）及样机前期准备。\r\n\r\n2.如以上可行，则我方可拟好技术规格提交电力公司以此作为最终版规格。\r\n\r\n3.项目代号：FIX05', '国际业务二部', '张红丽 ', '2015-12-05', '张红丽 2015-12-05 22:31:55', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
