INSERT INTO `crs_tabledata686` VALUES ('1753', '{6241C22B-3BAE-463C-BA62-ECAA3A87A207}', '0', 'INHE-0381', '2015-10-20 23:31:50', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'MR01', null, 'EnRafrique ', '', '摩洛哥', '', 'Mme Zohra Abib \r\nwww.enrafrique.com\r\nMobile: 00 212 6 77 44 15 45\r\nemail:z.abib@enrafrique.com', '', 'EnRafrique 公司致力于能源发展及方案实施，包括光伏能，太阳能，智能电表等方面。该公司设立于摩洛哥，具有15年以上的光伏方面的经验。', 'MR01', '04', '摩洛哥', '直接采购，我司提供电表，以及提供售电系统和集抄系统，并且为客户提供手机APP付费功能。', '请见附件项目情况说明。', '', '', '', '', '', '', '', '', '建议项目代号MR01.', '国际业务二部', '张柳芳(Alexie)', '2015-10-21', '张柳芳 2015-10-21 15:00:30', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
