INSERT INTO `crs_tabledata686` VALUES ('1767', '{6241C22B-3BAE-463C-BA62-ECAA3A87A221}', '60', 'INHE-0066', '2015-07-28 13:13:36', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', '白雪', null, 'Energomera CJSC', '', '俄罗斯 ', '', 'Anna Gavrirova', '', '客户为俄罗斯前三大表厂之一，占据电表主要市场，对分体式复费率RF集抄电表感兴趣，希望和我司进行ODM方式合作。', '白雪', '', '俄罗斯', 'TT支付方式', '拥有独立住房的客户群逐渐增多，适合这个客户群的分体式电能表的需求量逐渐上升。复费率PLC和RF分体式电能表是该公司拟开发的项目，欲在中国寻求合作伙伴。该项目的需求量不低于50万台', '', '', '', '', '', '', '', '', '', '国际业务一部', '邱洁', null, '', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1768', '{6241C22B-3BAE-463C-BA62-ECAA3A87A222}', '60', 'INHE-0066', '2015-07-28 12:13:26', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', '白云', null, '\"Aspan-Energy \" LTD', '', '哈萨克斯坦', '', 'Nikolay Chudznikov', '', '客户当地州电力公司，管辖20多万用户，', '白云', '', '哈萨克斯坦', 'TT支付方式', '客户当地窃电现象严重，同时抄表花费人力较多。欲上预付费和集抄系统，此前采购过其他公司预付费电表和系统，但是通信不稳定，因此想寻求新供应商。', '', '', '', '', '', '', '', '', '', '国际业务一部', '邱洁', null, '', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1769', '{6241C22B-3BAE-463C-BA62-ECAA3A87A223}', '0', 'JXINHE-1277', '2015-05-25 18:07:28', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'MW', null, 'IEK Group', '', '俄罗斯', '', '项目经理：Начигин Георгий Владимирович\r\n邮箱： nachigingv@iek.ru\r\n电话：+7 (495) 542-22-22#3650\r\n', '', '该客户主要做俄罗斯低压电器产品市场，市场范围很广泛，与俄罗斯很多大型国企电力公司等均有生意往来。客户在今年4月中下旬到我司来访洽谈，同时也拜访了其他电表公司。', 'MW', '04', '俄罗斯', '客户从我司直接采购散件到俄罗斯去进行组装。考虑到注册和认证的问题，合作方式客户建议采用联合品牌的方式。', '客户目前在莫斯科郊区有自己的小的电表组装厂，组装厂的规模很小，主要是组装从中国浙江采购的简单表。现在打算进军俄罗斯智能电表市场。', '该客户公司实力相对比较好，在俄罗斯有很多国有企业和电力公司的合作，虽然是其他电力产品，但是实力相对比较好。', '', '', '', '', '', '', '', '', '国际业务一部', '李婉君 ', '2015-05-25', '李婉君 2015-05-25 21:08:02', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
