INSERT INTO `crs_tabledata686` VALUES ('1820', '{6241C22B-3BAE-463C-BA62-ECAA3A87A274}', '0', 'INHE-0228', '2015-01-25 19:01:39', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'BFN', null, 'TOGO ASSISTANCE SERVICES', '', '多哥', '', '老客户', '', '老客户', 'BFN', '03', '布基纳法索', '客户直接投标，我司作为供应商。', '', '', '42049', '2', '', '', '', '', '', '个人觉得有两款表可以选择：1）一体式不带通讯的非模块表（TN05的产品）2）不带通讯模块的模块表。\r\n请公司从成本评估，是否两款产品成本上有较大差异。（注意：有铅封帽特殊要求）。\r\n', '国际业务二部', '谭雯', '2015-01-25', '谭雯 2015-01-25 19:01:43', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
