INSERT INTO `crs_tabledata686` VALUES ('1822', '{6241C22B-3BAE-463C-BA62-ECAA3A87A276}', '0', 'INHE-0382', '2015-08-05 13:25:07', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'BFN02', null, 'SOCIETE GENERALE D `ELECTRONIQUE', '', '多哥', '', '联系人：Azon Guillaume\r\nTEL/FAX: +228 22 22 13 55 /22 22 13 56\r\nGSM : +228 90 41 22 97 / 99 76 24 27\r\nE-mail：dg@sge-inter.com\r\n地址：Tokoin Habitat，70 rue des Hibiscus (Pharmacie Justices)\r\nBP. 13311, Lomé – Togo', '', 'Azon先生此前与我司法语组在西非法语区合作过多次，其中CDN是比较成功的，应该说双方都彼此熟悉', 'BFN02', '', '布基纳法索', '由AZON先生牵头，与SONABEL合作试点，拟立项BFN01', '由布方电力公司邀请，我司成为三家做试点的供应商之一，曾与谭雯、代理一行三人出差BFN01，给电力公司做过宣讲，对方反响不错，另外两家被邀请试点的厂商是Itron和Hexing', '', '', '', '', '', '', '', '', '（1）技术规格按照CDN技术规格执行\r\n\r\n（2）试点费用由我司和代理双方承担，一人一半', '国际业务二部', '温志斌 ', '2015-08-05', '温志斌 2015-08-05 15:28:16', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
