INSERT INTO `crs_tabledata686` VALUES ('1827', '{6241C22B-3BAE-463C-BA62-ECAA3A87A281}', '0', 'INHE-0329', '2014-06-19 17:01:09', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'TN08', null, 'TOGO ASSISTANCE SERVICES', '', '多哥', '', 'AZON GUILAUME ', '', '多次合作的投标代理', 'TN08', '03', '多哥', '电力公司邀请我司直接投标，但所提出的投标保函对银行有要求，我们不能满足。正与我们的客户商讨，是否能由代理商提供投标保函，由我司直接投标。', '', '', '2014年7月15日', '2', '', '', '', '', '我司开具投标保函', '项目代码：ＴＮ０８.　\r\n此项目所在市场是老客户。此次由我负责，谭雯协助投标。', '国际业务二部', '李明亮 ', '2014-06-23', '李明亮 2014-06-23 16:12:59', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1828', '{6241C22B-3BAE-463C-BA62-ECAA3A87A282}', '0', 'INHE-0329', '2014-06-19 17:01:09', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'TN08', null, 'TOGO ASSISTANCE SERVICES', '', '多哥', '', 'AZON GUILAUME ', '', '多次合作的投标代理', 'TN08', '03', '多哥', '电力公司邀请我司直接投标，但所提出的投标保函对银行有要求，我们不能满足。正与我们的客户商讨，是否能由代理商提供投标保函，由我司直接投标。', '', '', '2014年7月15日', '2', '', '', '', '', '我司开具投标保函', '项目代码：ＴＮ０８.　\r\n此项目所在市场是老客户。此次由我负责，谭雯协助投标。', '国际业务二部', '李明亮 ', '2014-06-23', '李明亮 2014-06-23 16:12:59', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1829', '{6241C22B-3BAE-463C-BA62-ECAA3A87A283}', '0', 'INHE-0228', '2015-03-03 20:45:21', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'TN09', null, 'SOCIETE GENERALE D `ELECTRONIQUE', '', '多哥', '', 'AZON GUILLAUME\r\n', '', '老客户', 'TN09', '', '多哥', '项目类型：目前是运作项目，后期可能是通过招投标的形式发出', '客户反馈TN电力公司2015招标的所有产品将都是分体式电表（此前一直是一体式，无通讯方式），现在已经有几个厂家将自己的DIN分体式的表送给电力公司测试，包括HEXING（Global Evoluation）。\r\n由于电力公司对我们已供货的产品还比较满意，因此电力公司希望我们也能提供样机测试。\r\n由于目前已提供样机厂家的样机都不带端盖和表箱，因此我打算供样的方案为：\r\nDIN双表位表箱，内置一只PLC表，和一只双绞线表（不带断路器，因为TN电力公司使用的是电流可调节式的断路器）。\r\n\r\n电力公司暂无技术规格', '', '', '1', '', '', '', '', '', '项目代码：TN09', '国际业务二部', '谭雯', '2015-03-04', '谭雯 2015-03-04 08:52:46', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1830', '{6241C22B-3BAE-463C-BA62-ECAA3A87A284}', '0', 'INHE-0228', '2015-03-03 20:45:21', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'TN09', null, 'SOCIETE GENERALE D `ELECTRONIQUE', '', '多哥', '', 'AZON GUILLAUME\r\n', '', '老客户', 'TN09', '', '多哥', '项目类型：目前是运作项目，后期可能是通过招投标的形式发出', '客户反馈TN电力公司2015招标的所有产品将都是分体式电表（此前一直是一体式，无通讯方式），现在已经有几个厂家将自己的DIN分体式的表送给电力公司测试，包括HEXING（Global Evoluation）。\r\n由于电力公司对我们已供货的产品还比较满意，因此电力公司希望我们也能提供样机测试。\r\n由于目前已提供样机厂家的样机都不带端盖和表箱，因此我打算供样的方案为：\r\nDIN双表位表箱，内置一只PLC表，和一只双绞线表（不带断路器，因为TN电力公司使用的是电流可调节式的断路器）。\r\n\r\n电力公司暂无技术规格', '', '', '1', '', '', '', '', '', '项目代码：TN09', '国际业务二部', '谭雯', '2015-03-04', '谭雯 2015-03-04 08:52:46', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
