INSERT INTO `crs_tabledata686` VALUES ('1832', '{6241C22B-3BAE-463C-BA62-ECAA3A87A286}', '0', 'INHE-0382', '2015-10-10 19:30:37', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'TN10', null, 'SOCIETE GENERALE D `ELECTRONIQUE', '', '多哥', '', '联系人：Azon Guillaume\r\nTEL/FAX: +228 22 22 13 55 /22 22 13 56\r\nGSM : +228 90 41 22 97 / 99 76 24 27\r\nE-mail：dg@sge-inter.com\r\n地址：Tokoin Habitat，70 rue des Hibiscus (Pharmacie Justices)\r\nBP. 13311, Lomé – Togo', '', 'Azon先生此前与我司法语组在西非法语区合作过多次，其中CDN是比较成功的，应该说双方都彼此熟悉', 'TN10', '03', '多哥', '由AZON先生牵头，参与CEET的投标', '', '', '42307', '1', '当地社会状况良好，治安不错', '规范', '', '', '保函由代理在项目所在国开出，相对国内更加快速', '此次投标由代理代为参加投标，CEET是多哥电力公司，考虑到代理在当地的实力，因此比较有希望中标', '国际业务二部', '温志斌 ', '2015-10-10', '温志斌 2015-10-10 19:37:49', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1833', '{6241C22B-3BAE-463C-BA62-ECAA3A87A287}', '0', 'INHE-0381', '2015-03-09 09:20:58', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'FDJ01', null, 'Novabase', '', '佛得角', '', 'Jo&atilde;o Faria\r\n+351 925 968 187 mol\r\njoao.faria@novabase.pt\r\n', '', '客户从事于能源与公用事业行业。是葡萄牙的，之前合作过安哥拉市场招标项目，但是没有结果，曾经下过样机买过演示箱。', 'FDJ01', '03', '佛得角', '客户直接投标并提供保函，我司作为供应商', '2013年，佛得角为了提高ELECTRA用户的能源质量服务，开始了“节能降损和电能质量改善计划”的计划， 此次项目是其中的一个主要项目。', '', '2015.3.23', '无', '', '', '', '', '由客户开立', '建议项目代码：FDJ01', '国际业务二部', '张柳芳(Alexie)', '2015-03-09', '张柳芳 2015-03-09 09:51:13', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
