INSERT INTO `crs_tabledata686` VALUES ('1839', '{6241C22B-3BAE-463C-BA62-ECAA3A87A293}', '0', 'INHE-0329', '2014-12-19 17:51:53', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'CN05', null, 'SOCIETE NATIONALE D `ELECTRICITE SARL', '', '刚果金', '', 'SNEL\r\n', '', '刚果金国家电力公司SNEL，此次利用世行融资公开招标。', 'CN05', '03', '刚果金', '公司决定由代理SGE投标开保函，我司协助投标。', '刚果金国家电力公司SNEL，此次利用世行融资公开招标。根据标书要求，估计此招标被某个供应商在背后运作。', '', '2015年1月8日', '各一只', '政治不稳定，经济落后。客户信用与财务实力较弱。', '不规范，易受操作。', '客户信用与财务实力较弱。此次由世行融资。', '技术要求不高，现有资料可以满足。', '由代理开保函。', 'CN市场此前的业务由谭雯做，郭总建议此次投标由我负责。按照惯例项目代码拟定为CN05。但是具体电表选型以利于投标竞争还需要与代理商沟通再决定。', '国际业务二部', '李明亮 ', '2014-12-22', '李明亮 2014-12-22 15:02:32', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
