INSERT INTO `crs_tabledata686` VALUES ('1862', '{6241C22B-3BAE-463C-BA62-ECAA3A87A316}', '0', 'INHE-0329', '2014-06-23 10:57:50', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'EW07', null, 'TOGO ASSISTANCE SERVICES', '', '卢旺达', '', 'AZON GUILAUME', '', '多次合作投标的客户', 'EW07', '03', '卢旺达', '客户直接投标，我司作为其供应商', '新招标', '', '2014年8月14日', '2', '', '', '', '', '', '新项目拟用代码ＥＷ０７.\r\n此项目由我负责。谭雯协助投标。', '国际业务二部', '李明亮 ', '2014-06-23', '李明亮 2014-06-23 14:25:56', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1863', '{6241C22B-3BAE-463C-BA62-ECAA3A87A317}', '0', 'INHE-0228', '2014-07-09 08:52:07', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'EW08', null, 'LINE APPS LTD', '', '卢旺达', '', 'J. Remy MUHIRE\r\nTél. +250 785 383 100\r\nE-mail : jeanremy1806@gmail.com\r\n', '', '电力公司四大售电分销商之一', 'EW08', '04', '卢旺达', '客户直接向我司采购。\r\n付款方式：50%现金预付款（已收款）+ 50%尾款TT\r\n', '客户是电力公司的第三方售电，他们的佣金为售电金额的7%。\r\n客户公司自己开发了用于手机上的转账APP，此APP也可以用于购电。\r\n客户现在想通过他们的APP，客户购完电之后，直接可以将TOKEN下发到表计，特别是对于老人，或是残疾人比较便利。\r\n远程下发TOKEN功能，将使得他们和其他第三方相比更有优势，因此能吸引到跟多的客户，进而有更多的盈利。\r\n客户的计划是将自己采购电表，然后免费给用户装表。用户越多，利润越多。', '通过与客户的沟通，我们将给客户提供一批GPRS的模块和下发TOKEN的相关软件（需要与客户的软件做个简单的接口）。\r\n\r\n对于我司而言，这个项目的意义在于，可以在当地市场引进我司的集抄系统，并通过此客户做个小试点，以便借此运行当地的一套技术规格，将更有利于这个市场以后的竞争。', '', '', '', '', '', '', '', '项目代码EW08.\r\n\r\n麻烦公司给出交期。\r\n\r\n客户周5离开中国，希望走之前能带走一台三相和一台单相的样机，请问是否有可能？？\r\n', '国际业务二部', '谭雯', '2014-07-09', '谭雯 2014-07-09 08:57:08', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1864', '{6241C22B-3BAE-463C-BA62-ECAA3A87A318}', '0', 'INHE-0228', '2014-07-09 08:52:07', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'EW08', null, 'LINE APPS LTD', '', '卢旺达', '', 'J. Remy MUHIRE\r\nTél. +250 785 383 100\r\nE-mail : jeanremy1806@gmail.com\r\n', '', '电力公司四大售电分销商之一', 'EW08', '04', '卢旺达', '客户直接向我司采购。\r\n付款方式：50%现金预付款（已收款）+ 50%尾款TT\r\n', '客户是电力公司的第三方售电，他们的佣金为售电金额的7%。\r\n客户公司自己开发了用于手机上的转账APP，此APP也可以用于购电。\r\n客户现在想通过他们的APP，客户购完电之后，直接可以将TOKEN下发到表计，特别是对于老人，或是残疾人比较便利。\r\n远程下发TOKEN功能，将使得他们和其他第三方相比更有优势，因此能吸引到跟多的客户，进而有更多的盈利。\r\n客户的计划是将自己采购电表，然后免费给用户装表。用户越多，利润越多。', '通过与客户的沟通，我们将给客户提供一批GPRS的模块和下发TOKEN的相关软件（需要与客户的软件做个简单的接口）。\r\n\r\n对于我司而言，这个项目的意义在于，可以在当地市场引进我司的集抄系统，并通过此客户做个小试点，以便借此运行当地的一套技术规格，将更有利于这个市场以后的竞争。', '', '', '', '', '', '', '', '项目代码EW08.\r\n\r\n麻烦公司给出交期。\r\n\r\n客户周5离开中国，希望走之前能带走一台三相和一台单相的样机，请问是否有可能？？\r\n', '国际业务二部', '谭雯', '2014-07-09', '谭雯 2014-07-09 08:57:08', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1865', '{6241C22B-3BAE-463C-BA62-ECAA3A87A319}', '0', 'INHE-0381', '2015-07-15 22:44:12', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'EW09', null, 'ROYALCO ltd.', '', '卢旺达', '', 'LOCATION:P.O.BOX 3764 TOWN CITY,KIGALI.\r\n TELEPHONE: +250788306464/+250758306464/+250728306464 \r\nEMAIL: jyga02@yahoo.fr Royalco.limited@gmail.com \r\nwww.royalcolimited.com', '', '当地公司，成立于07年，主要从事器械供应和安装，基建方面较多。跟电力公司内部有联系。', 'EW09', '03', '卢旺达', '代理直接投标，开保函。我司作为供应商，提供技术支持。　', '此前有过EW07项目，电表产品和此次电表产品的技术规格大致相同，有少许修改。', '', '2015.08.06', '2', '', '较规范', '', '', '由客户开立', '建议项目代号为EW09.', '国际业务二部', '张柳芳(Alexie)', '2015-07-15', '张柳芳 2015-07-15 22:47:33', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
