INSERT INTO `crs_tabledata686` VALUES ('1885', '{6241C22B-3BAE-463C-BA62-ECAA3A87A339}', '0', 'INHE-0382', '2015-08-04 16:18:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'GHA', null, 'SOCIETE GENERALE D `ELECTRONIQUE', '', '多哥', '', '联系人：Azon Guillaume\r\nTEL/FAX: +228 22 22 13 55 /22 22 13 56\r\nGSM : +228 90 41 22 97 / 99 76 24 27\r\nE-mail：dg@sge-inter.com\r\n地址：Tokoin Habitat，70 rue des Hibiscus (Pharmacie Justices)\r\nBP. 13311, Lomé – Togo', '', 'Azon先生此前与我司法语组在西非法语区合作过多次，其中CDN是比较成功的，应该说双方都彼此熟悉', 'GHA', '', '加纳', '由AZON先生牵头，与ECG合作试点，拟立项GHA01', '我司在加纳做过产品宣讲后，双方商议由代理AZON协同银河一起开始做试点，500台表，详细需求见下表', '', '', '', '', '', '', '', '', '经过出差当地的市场调查，ECG公司八国九治，用多个供应商的多套管理系统，电表供应商也纷繁复杂，此次是我司在加纳市场一展身手的好机会，特别是Smart系统，可以统管ECG现有所有的表，项目有潜力，可以试点。\r\n\r\n立项项目代号为GHA01', '国际业务二部', '温志斌 ', '2015-08-04', '温志斌 2015-08-04 17:17:29', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
