INSERT INTO `crs_tabledata686` VALUES ('1897', '{6241C22B-3BAE-463C-BA62-ECAA3A87A351}', '0', 'INHE-0431', '2015-08-28 15:18:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'NA01', null, 'Tangent Technical Services/City of Windhoek', '', '纳米比亚', '', 'Eino Mvula\r\nTangent Technical Services\r\n+264811247624', '', '现在有两家代理同时在联系，计划同时投标,其中Tangent Technical Services在市政赢取过其他的小标案，但是电表是第一次操作，没有太多经验\r\n\r\n', 'NA01', '03', '纳米比亚', '我们提供FOB Shenzhen价格和公司及产品简介，代理参与投标', '招标方为WINDHOEK市政，WINDHOEK是纳米比亚的首都，也是全国最大的城市，有322，500人口\r\n\r\n此次是为期两年的投标，每次/季度采购最小量为500台/款', '', '2015年9月4日', '每款各2台', '1990年通过的宪法规定：纳米比亚是一个主权、独立、统一和世俗的共和国；实行三权分立、两院议会和总理内阁制。独立后，政局一直保持稳定。\r\n\r\n世界上海洋渔业资源最丰富的国家之一，铀、钻石等矿产资源和产量居非洲前列。矿业、渔业和农牧业为三大传统支柱产业，种植业、制造业较落后。\r\n\r\n人均国内生产总值	约7097美元　　经济增长率	        4%', '', '', '', '代理参与投标', '我接手后的第一个纳米比亚的投标，数量不是很大，但是纳米比亚总人口才240万人口，而温得和克又是首都，所以此项目对纳米比亚的后续开发还是可以有很大的推动作用\r\n\r\n同时我们现在有两家代理商同时在合作，此次投标也可以作为一次实地检测的机会，以便制定接下来的合作和开发计划', '国际业务二部', '刘佩(Ted)', '2015-08-31', '刘佩 2015-08-31 09:15:58', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1898', '{6241C22B-3BAE-463C-BA62-ECAA3A87A352}', '0', 'INHE-0431', '2015-08-28 15:18:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'NA01', null, 'Tangent Technical Services/City of Windhoek', '', '纳米比亚', '', 'Eino Mvula\r\nTangent Technical Services\r\n+264811247624', '', '现在有两家代理同时在联系，计划同时投标,其中Tangent Technical Services在市政赢取过其他的小标案，但是电表是第一次操作，没有太多经验\r\n\r\n', 'NA01', '03', '纳米比亚', '我们提供FOB Shenzhen价格和公司及产品简介，代理参与投标', '招标方为WINDHOEK市政，WINDHOEK是纳米比亚的首都，也是全国最大的城市，有322，500人口\r\n\r\n此次是为期两年的投标，每次/季度采购最小量为500台/款', '', '2015年9月4日', '每款各2台', '1990年通过的宪法规定：纳米比亚是一个主权、独立、统一和世俗的共和国；实行三权分立、两院议会和总理内阁制。独立后，政局一直保持稳定。\r\n\r\n世界上海洋渔业资源最丰富的国家之一，铀、钻石等矿产资源和产量居非洲前列。矿业、渔业和农牧业为三大传统支柱产业，种植业、制造业较落后。\r\n\r\n人均国内生产总值	约7097美元　　经济增长率	        4%', '', '', '', '代理参与投标', '我接手后的第一个纳米比亚的投标，数量不是很大，但是纳米比亚总人口才240万人口，而温得和克又是首都，所以此项目对纳米比亚的后续开发还是可以有很大的推动作用\r\n\r\n同时我们现在有两家代理商同时在合作，此次投标也可以作为一次实地检测的机会，以便制定接下来的合作和开发计划', '国际业务二部', '刘佩(Ted)', '2015-08-31', '刘佩 2015-08-31 09:15:58', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1899', '{6241C22B-3BAE-463C-BA62-ECAA3A87A353}', '0', 'INHE-0431', '2015-09-06 08:56:53', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'IP', null, 'IdealPrepaid Pty(Ltd)', '', '南非', '', 'Alon Greenberg \r\nTel: (082) 9495998', '', 'Idealprepaid 是南非私人部门(房东租户)的一个比较大的系统和表的提供商。他们一年可以销售30,000台左右简单的 STS标准的预付费表，无其它任何特殊功能。据他反馈现在购买的是附件1里的这一款表，采购价在300兰特，卖价是550兰特左右。\r\n\r\n同时他们现在也在参与市政公司的Smart Meter的招标，已经中标的有一个DURBAN的项目，数量是11000 台，要求是他们的系统要能管理我们的表，包括附件2所示的功能。 另外他说他们已经和海兴的人有沟通过，也买了他们的样品，但是海兴的人在技术回复', 'IP', '04', '南非', '样品100%付款.\r\n大货50%预付费+50%货前付款', '', '', '', '', '', '', '', '', '', 'Idealprepaid目前主要是两个方面合作可能性:\r\n\r\n1.Durban的11,000台的订单,我们的样品需要和他们的系统进行配套调试.\r\n2.我们的STS代码表是否可以取代他现有的Landis Gyr.\r\n\r\n目前计划提供的是1*单相GPRS+1*三相GPRS表+TP DEMO.如果他可以在不需要我们大力配合的情况下调通,直接跟进其下达大货订单. 如果他需要我们额外的人员的进行相关协助,我会要求他们下达不少于1000台订单+50%预付款或者50,000美金的订金.', '国际业务二部', '刘佩(Ted)', '2015-09-06', '刘佩 2015-09-06 10:58:16', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1900', '{6241C22B-3BAE-463C-BA62-ECAA3A87A354}', '0', 'INHE-0431', '2015-09-06 08:56:53', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'IP', null, 'IdealPrepaid Pty(Ltd)', '', '南非', '', 'Alon Greenberg \r\nTel: (082) 9495998', '', 'Idealprepaid 是南非私人部门(房东租户)的一个比较大的系统和表的提供商。他们一年可以销售30,000台左右简单的 STS标准的预付费表，无其它任何特殊功能。据他反馈现在购买的是附件1里的这一款表，采购价在300兰特，卖价是550兰特左右。\r\n\r\n同时他们现在也在参与市政公司的Smart Meter的招标，已经中标的有一个DURBAN的项目，数量是11000 台，要求是他们的系统要能管理我们的表，包括附件2所示的功能。 另外他说他们已经和海兴的人有沟通过，也买了他们的样品，但是海兴的人在技术回复', 'IP', '04', '南非', '样品100%付款.\r\n大货50%预付费+50%货前付款', '', '', '', '', '', '', '', '', '', 'Idealprepaid目前主要是两个方面合作可能性:\r\n\r\n1.Durban的11,000台的订单,我们的样品需要和他们的系统进行配套调试.\r\n2.我们的STS代码表是否可以取代他现有的Landis Gyr.\r\n\r\n目前计划提供的是1*单相GPRS+1*三相GPRS表+TP DEMO.如果他可以在不需要我们大力配合的情况下调通,直接跟进其下达大货订单. 如果他需要我们额外的人员的进行相关协助,我会要求他们下达不少于1000台订单+50%预付款或者50,000美金的订金.', '国际业务二部', '刘佩(Ted)', '2015-09-06', '刘佩 2015-09-06 10:58:16', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1901', '{6241C22B-3BAE-463C-BA62-ECAA3A87A355}', '0', 'INHE-0431', '2015-12-03 03:37:42', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'SIA02', null, 'I4 Power technology', '', '南非', '', 'Ajay Jekison\r\n0027824477900\r\n35 Wierda road West Wierda Valley Sandton 2196 Gauteng South Africa', '', '之前SIA01项目有采购过1400台电表，我们也有商务和技术人员过去协助安装，但是由于客户自身还有市政的问题，电表最近才开始安装，不过已经装完700多台，现在计划把我们在当地的时候和他一起做技术展示的标案的订单下达下来', 'SIA02', '04', '南非', '50% T/T 生产前 + 50% T/T发货前', '我在当地出差时一起去过市政做技术展示，当时整个评标会的人员对我们都较满意。本来发标的结果是有两家分标，但是代理又和市政公司进行了最后争取，现在整个订单只给一个供应商。', '', '不适用', '不适用', '', '', '', '', '', '', '国际业务二部', '刘佩(Ted)', '2015-12-03', '刘佩 2015-12-03 04:33:48', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1902', '{6241C22B-3BAE-463C-BA62-ECAA3A87A356}', '0', 'INHE-0431', '2015-12-03 03:37:42', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'SIA02', null, 'I4 Power technology', '', '南非', '', 'Ajay Jekison\r\n0027824477900\r\n35 Wierda road West Wierda Valley Sandton 2196 Gauteng South Africa', '', '之前SIA01项目有采购过1400台电表，我们也有商务和技术人员过去协助安装，但是由于客户自身还有市政的问题，电表最近才开始安装，不过已经装完700多台，现在计划把我们在当地的时候和他一起做技术展示的标案的订单下达下来', 'SIA02', '04', '南非', '50% T/T 生产前 + 50% T/T发货前', '我在当地出差时一起去过市政做技术展示，当时整个评标会的人员对我们都较满意。本来发标的结果是有两家分标，但是代理又和市政公司进行了最后争取，现在整个订单只给一个供应商。', '', '不适用', '不适用', '', '', '', '', '', '', '国际业务二部', '刘佩(Ted)', '2015-12-03', '刘佩 2015-12-03 04:33:48', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1903', '{6241C22B-3BAE-463C-BA62-ECAA3A87A357}', '0', 'INHE-0431', '2015-10-29 15:54:02', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'U17', null, 'Umeme Limited', '', '乌干达', '', 'Procurement Manager UMEME Limited; Amatos Mwebeiha\r\nTel:+256 312 360 600  \r\nHP:+256 776 360 762      \r\nEmail:amatos.mwebeiha@umeme.co.ug ', '', 'UMEME作为乌干达国家级别的电力公司是乌干达市场上最主要的一家电力公司，据采购经理说一年的采购量在10万－20万台之间', 'U17', '03', '乌干达', '两种方案备选：\r\n1.由当地经销商直接参标，我们协助（在我们和UMEME暂时不熟悉的情况下是较好的选择，可有有效规避风险）\r\n2.我们直接参与，当地人做为掮客帮我们做游说和其它的相关工作', 'Umeme为期三年的采购合，每年的计划采购量在10万到20万之间，包括单相DIN表和三相BS表', '', '还未招标', '待定', '政治基本稳定，但是2016年2月份大选，所以有一定的不确定性。这也是他们的招标从9月份推迟到现在也没有进展的一个很重要原因（主要投资人是南非和英国公司，他们考虑到自己投资回报的稳定性）', '', '', '', '', '在项目开标前通过对现在经销商的拜访确认他们的实力和合作方式后对项目的标书进行运作，争取拿下订单', '国际业务二部', '刘佩(Ted)', '2015-10-29', '刘佩 2015-10-29 16:18:38', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1904', '{6241C22B-3BAE-463C-BA62-ECAA3A87A358}', '0', 'INHE-0431', '2015-10-29 15:54:02', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'U17', null, 'Umeme Limited', '', '乌干达', '', 'Procurement Manager UMEME Limited; Amatos Mwebeiha\r\nTel:+256 312 360 600  \r\nHP:+256 776 360 762      \r\nEmail:amatos.mwebeiha@umeme.co.ug ', '', 'UMEME作为乌干达国家级别的电力公司是乌干达市场上最主要的一家电力公司，据采购经理说一年的采购量在10万－20万台之间', 'U17', '03', '乌干达', '两种方案备选：\r\n1.由当地经销商直接参标，我们协助（在我们和UMEME暂时不熟悉的情况下是较好的选择，可有有效规避风险）\r\n2.我们直接参与，当地人做为掮客帮我们做游说和其它的相关工作', 'Umeme为期三年的采购合，每年的计划采购量在10万到20万之间，包括单相DIN表和三相BS表', '', '还未招标', '待定', '政治基本稳定，但是2016年2月份大选，所以有一定的不确定性。这也是他们的招标从9月份推迟到现在也没有进展的一个很重要原因（主要投资人是南非和英国公司，他们考虑到自己投资回报的稳定性）', '', '', '', '', '在项目开标前通过对现在经销商的拜访确认他们的实力和合作方式后对项目的标书进行运作，争取拿下订单', '国际业务二部', '刘佩(Ted)', '2015-10-29', '刘佩 2015-10-29 16:18:38', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1905', '{6241C22B-3BAE-463C-BA62-ECAA3A87A359}', '0', 'INHE-0380', '2015-03-24 14:36:25', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ZTC', null, 'Finmark Industries (Pvt) Ltd', '', '津巴布韦', '', 'Clint Mtungwazi Group Managing Director Finmark-Holdings(pvt) Ltd\r\n\r\n                              Tel:+263-4-777480/9', '', '此公司经营电力设备，如电线，开关，变压器，机械式电表等业务，分公司经营计算机等其他业务。客户和电力公司关系好，营销能力强，执行力强，已和我司合作ZEC1项目', 'ZTC', '03', '津巴布韦', '我司作为厂家支持，由代理投标', '1：ZA项目废标后，津巴布韦电力局重新招标4个批次共计15万台BS,DIN 单相PLC通信分体预付费代码表。\r\n2：LOT A 为BS单相表6W台； LOT B 为BS单相表4W台； LOT C 为DIN单相表3W台； LOT D 为DIN单相表2W台。\r\n3：标书评估，技术部分占70%，商务部分占30%。投标企业必须达到技术部分要求的80%以上\r\n4：此次至少2家公司中标，最多不超过4家公司\r\n5：本次投标不需要中标方安装电表，只需提供电表', '', '2015年4月15', '单相BS，DIN各两台', '', '', '', '1：需要客服部协助提供部分技术资料；2需要客服部阅读标书文件，指出不符点', '代理投标，代理开立', '建议立项. 项目代号;ZTC', '国际业务二部', '何健', '2015-03-24', '何健 2015-03-24 16:37:25', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1906', '{6241C22B-3BAE-463C-BA62-ECAA3A87A360}', '0', 'INHE-0380', '2015-03-24 14:36:25', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ZTC', null, 'Finmark Industries (Pvt) Ltd', '', '津巴布韦', '', 'Clint Mtungwazi Group Managing Director Finmark-Holdings(pvt) Ltd\r\n\r\n                              Tel:+263-4-777480/9', '', '此公司经营电力设备，如电线，开关，变压器，机械式电表等业务，分公司经营计算机等其他业务。客户和电力公司关系好，营销能力强，执行力强，已和我司合作ZEC1项目', 'ZTC', '03', '津巴布韦', '我司作为厂家支持，由代理投标', '1：ZA项目废标后，津巴布韦电力局重新招标4个批次共计15万台BS,DIN 单相PLC通信分体预付费代码表。\r\n2：LOT A 为BS单相表6W台； LOT B 为BS单相表4W台； LOT C 为DIN单相表3W台； LOT D 为DIN单相表2W台。\r\n3：标书评估，技术部分占70%，商务部分占30%。投标企业必须达到技术部分要求的80%以上\r\n4：此次至少2家公司中标，最多不超过4家公司\r\n5：本次投标不需要中标方安装电表，只需提供电表', '', '2015年4月15', '单相BS，DIN各两台', '', '', '', '1：需要客服部协助提供部分技术资料；2需要客服部阅读标书文件，指出不符点', '代理投标，代理开立', '建议立项. 项目代号;ZTC', '国际业务二部', '何健', '2015-03-24', '何健 2015-03-24 16:37:25', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1907', '{6241C22B-3BAE-463C-BA62-ECAA3A87A361}', '0', 'INHE-0051', '2014-12-18 09:37:27', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PX', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '此市场已多次合作的代理', 'PX', '03', '肯尼亚', '银河直接参加投标，代理W协助', '1. 局限性招标，推测有3家受邀参加此项目，海兴，思达和银河。具体正在了解中。\r\n2. 技术规格和PY一样，需求产品为单相预付费电表，双绞线，PLC,RF，三种通讯方式，各5万台\r\n3.评标规则为：3种产品分开评标，评标价最低者中标。此项目对交期要求严格，要求2015年1月30日可交货到电力公司参考，评审中会考虑供应商对交期的回复。\r\n4.此项目3款产品，各提交1台样机。\r\n5.需开立投标保函，金额为25000USD\r\n6.截标时间为2015年1月7日', '', '2015年1月7日', '3台', '', '', '', '1.需紧急办理投标保函\r\n2.需紧急制作投标样机\r\n', '投标保函金额约为25000USD，通过当地银行转开。', '', '国际业务二部', '盛燕', '2014-12-18', '盛燕 2014-12-18 09:37:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1908', '{6241C22B-3BAE-463C-BA62-ECAA3A87A362}', '0', 'INHE-0051', '2014-12-18 09:37:27', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PX', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '此市场已多次合作的代理', 'PX', '03', '肯尼亚', '银河直接参加投标，代理W协助', '1. 局限性招标，推测有3家受邀参加此项目，海兴，思达和银河。具体正在了解中。\r\n2. 技术规格和PY一样，需求产品为单相预付费电表，双绞线，PLC,RF，三种通讯方式，各5万台\r\n3.评标规则为：3种产品分开评标，评标价最低者中标。此项目对交期要求严格，要求2015年1月30日可交货到电力公司参考，评审中会考虑供应商对交期的回复。\r\n4.此项目3款产品，各提交1台样机。\r\n5.需开立投标保函，金额为25000USD\r\n6.截标时间为2015年1月7日', '', '2015年1月7日', '3台', '', '', '', '1.需紧急办理投标保函\r\n2.需紧急制作投标样机\r\n', '投标保函金额约为25000USD，通过当地银行转开。', '', '国际业务二部', '盛燕', '2014-12-18', '盛燕 2014-12-18 09:37:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1909', '{6241C22B-3BAE-463C-BA62-ECAA3A87A363}', '0', 'INHE-0051', '2014-12-18 09:37:27', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PX', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '此市场已多次合作的代理', 'PX', '03', '肯尼亚', '银河直接参加投标，代理W协助', '1. 局限性招标，推测有3家受邀参加此项目，海兴，思达和银河。具体正在了解中。\r\n2. 技术规格和PY一样，需求产品为单相预付费电表，双绞线，PLC,RF，三种通讯方式，各5万台\r\n3.评标规则为：3种产品分开评标，评标价最低者中标。此项目对交期要求严格，要求2015年1月30日可交货到电力公司参考，评审中会考虑供应商对交期的回复。\r\n4.此项目3款产品，各提交1台样机。\r\n5.需开立投标保函，金额为25000USD\r\n6.截标时间为2015年1月7日', '', '2015年1月7日', '3台', '', '', '', '1.需紧急办理投标保函\r\n2.需紧急制作投标样机\r\n', '投标保函金额约为25000USD，通过当地银行转开。', '', '国际业务二部', '盛燕', '2014-12-18', '盛燕 2014-12-18 09:37:28', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1910', '{6241C22B-3BAE-463C-BA62-ECAA3A87A364}', '0', 'INHE-0051', '2015-04-08 10:17:45', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PX02', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', 'KPLC是肯尼亚电力公司，负责电表采购，已多次合作。', 'PX02', '03', '肯尼亚', '银河直接投标，代理W协助', '1. 局限性招标，推测有3家受邀参加此项目，海兴，思达和银河。具体正在了解中。 \r\n2. 技术规格见附件，需求产品为单相预付费电表，双绞线通讯分体表，LOT1有18万台，LOT2有12万台\r\n3.评标规则为：2个LOT分开评标，一个投标者可以投2个LOT，但是只能中1个LOT，除非和第二名价格相差大于10%。\r\n4.此项目对交期要求严格，要求2015年5月15日交货到电力公司仓库，评审中会考虑供应商对交期的回复。 此项目将空运。\r\n5.此项目需提交1台样机。 \r\n6.需开立投标保函，金额为30000USD', '', '42115', '1', '', '', '', '1.需紧急办理投标保函 \r\n2.需紧急制作投标样机 \r\n3.需紧急制作投标资料', '投标保函金额约为30000USD，通过当地银行转开。', '', '国际业务二部', '盛燕', '2015-04-08', '盛燕 2015-04-08 10:29:12', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1911', '{6241C22B-3BAE-463C-BA62-ECAA3A87A365}', '0', 'INHE-0051', '2015-04-08 10:17:45', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PX02', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', 'KPLC是肯尼亚电力公司，负责电表采购，已多次合作。', 'PX02', '03', '肯尼亚', '银河直接投标，代理W协助', '1. 局限性招标，推测有3家受邀参加此项目，海兴，思达和银河。具体正在了解中。 \r\n2. 技术规格见附件，需求产品为单相预付费电表，双绞线通讯分体表，LOT1有18万台，LOT2有12万台\r\n3.评标规则为：2个LOT分开评标，一个投标者可以投2个LOT，但是只能中1个LOT，除非和第二名价格相差大于10%。\r\n4.此项目对交期要求严格，要求2015年5月15日交货到电力公司仓库，评审中会考虑供应商对交期的回复。 此项目将空运。\r\n5.此项目需提交1台样机。 \r\n6.需开立投标保函，金额为30000USD', '', '42115', '1', '', '', '', '1.需紧急办理投标保函 \r\n2.需紧急制作投标样机 \r\n3.需紧急制作投标资料', '投标保函金额约为30000USD，通过当地银行转开。', '', '国际业务二部', '盛燕', '2015-04-08', '盛燕 2015-04-08 10:29:12', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1912', '{6241C22B-3BAE-463C-BA62-ECAA3A87A366}', '0', 'INHE-0051', '2015-04-29 19:02:21', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'A40', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472　\r\n', '', '此市场已多次合作的代理', 'A40', '03', '肯尼亚', '银河直接投标\r\n标书未规定一个厂家只能通过一个代理投标，也未说明只能厂家投标。', '1.招标方是KPLC，项目资金来自肯尼亚政府，指定非洲发展银行作为融资银行\r\n2.5月11日举行标前会议，不需要去安装现场参观\r\n3.KPLC的项目组负责此项目，和PX02，PY02项目不一样\r\n4.交期要求为最迟2016年8月30日交货到内罗毕，肯尼亚\r\n5.需开立投标保函12万美金\r\n6.中标后供货数量变动范围为正负15%\r\n7.付款条件：对于进口的货物，10%预付款；发货后80%余款通过中标方所在国的银行开立不可撤销保兑信用证；货物全部交付后，采购方提供收货凭证和验收证明后30天内支付余款10%。采', '', '2015年6月5日', '各1台', '', '', '', '', '12万美金，需财务协助', '建议立项', '国际业务二部', '盛燕', '2015-04-29', '盛燕 2015-04-29 19:22:01', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1913', '{6241C22B-3BAE-463C-BA62-ECAA3A87A367}', '0', 'INHE-0051', '2015-04-29 19:02:21', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'A40', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472　\r\n', '', '此市场已多次合作的代理', 'A40', '03', '肯尼亚', '银河直接投标\r\n标书未规定一个厂家只能通过一个代理投标，也未说明只能厂家投标。', '1.招标方是KPLC，项目资金来自肯尼亚政府，指定非洲发展银行作为融资银行\r\n2.5月11日举行标前会议，不需要去安装现场参观\r\n3.KPLC的项目组负责此项目，和PX02，PY02项目不一样\r\n4.交期要求为最迟2016年8月30日交货到内罗毕，肯尼亚\r\n5.需开立投标保函12万美金\r\n6.中标后供货数量变动范围为正负15%\r\n7.付款条件：对于进口的货物，10%预付款；发货后80%余款通过中标方所在国的银行开立不可撤销保兑信用证；货物全部交付后，采购方提供收货凭证和验收证明后30天内支付余款10%。采', '', '2015年6月5日', '各1台', '', '', '', '', '12万美金，需财务协助', '建议立项', '国际业务二部', '盛燕', '2015-04-29', '盛燕 2015-04-29 19:22:01', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1914', '{6241C22B-3BAE-463C-BA62-ECAA3A87A368}', '0', 'INHE-0051', '2015-04-29 19:26:32', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PY02', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '此市场已多次合作的代理　', 'PY02', '03', '肯尼亚', '标书表明厂家和代理都可以投标，一个厂家只能通过一个代理投标。\r\n银河直接投标', '1.3年框架合同招标，需求数量见附件。总共需求4款产品：DIN CABLE分体，DIN PLC分体，三相BS PLC分体，三相简单表。第一年合同期间最少需求量为70万台，3年最多需求120.5万台，此数量有30%上浮空间。\r\n2.每个LOT每个ITEM产品分开评标，最低评标价中标。\r\n投标方不能同时中标所有LOT中同样的产品，除非价格第二的投标方高于5%，这种情况下，价格最底投标方可中标同款产品。\r\n若2个价格最低者的价格一样，则平分数量。\r\n3.交期要求严格，2015年8月份需交至少1半，标书有明确要求', '', '2015年5月28日', '各2台', '', '', '', '', '3,000,000肯先令，将开立40，000USD保函', '此次难点在技术方面，需严格按照标书及时制作样机。', '国际业务二部', '盛燕', '2015-04-29', '盛燕 2015-04-29 19:46:14', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1915', '{6241C22B-3BAE-463C-BA62-ECAA3A87A369}', '0', 'INHE-0051', '2015-08-20 11:34:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PB', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '肯尼亚国家电力公司', 'PB', '03', '肯尼亚', '银河投标，还是代理投标，待进一步沟通确认\r\n标书要求：厂家或代理都可以投标，厂家可以通过多家代理投标。', '表箱框架合同招标，8月13日公开招标，9月9日截标，截标前需提交1台样机\r\n', '', '42256', '1', '', '', '', '商务资料难点：\r\n1.表箱材料需通过ISO75认证，并且需提交证书\r\n2.需提供表箱型式测试报告，测试机构需是IEC17025认可的实验室\r\n\r\n', '根据合作方式，决定银河还是代理开立保函\r\n保函金额预计8万美金', '建议投标', '国际业务二部', '盛燕', '2015-08-20', '盛燕 2015-08-20 11:43:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1916', '{6241C22B-3BAE-463C-BA62-ECAA3A87A370}', '0', 'INHE-0051', '2015-08-20 11:34:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PB', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '肯尼亚国家电力公司', 'PB', '03', '肯尼亚', '银河投标，还是代理投标，待进一步沟通确认\r\n标书要求：厂家或代理都可以投标，厂家可以通过多家代理投标。', '表箱框架合同招标，8月13日公开招标，9月9日截标，截标前需提交1台样机\r\n', '', '42256', '1', '', '', '', '商务资料难点：\r\n1.表箱材料需通过ISO75认证，并且需提交证书\r\n2.需提供表箱型式测试报告，测试机构需是IEC17025认可的实验室\r\n\r\n', '根据合作方式，决定银河还是代理开立保函\r\n保函金额预计8万美金', '建议投标', '国际业务二部', '盛燕', '2015-08-20', '盛燕 2015-08-20 11:43:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1917', '{6241C22B-3BAE-463C-BA62-ECAA3A87A371}', '0', 'INHE-0051', '2015-08-20 11:34:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PB', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', '肯尼亚国家电力公司', 'PB', '03', '肯尼亚', '银河投标，还是代理投标，待进一步沟通确认\r\n标书要求：厂家或代理都可以投标，厂家可以通过多家代理投标。', '表箱框架合同招标，8月13日公开招标，9月9日截标，截标前需提交1台样机\r\n', '', '42256', '1', '', '', '', '商务资料难点：\r\n1.表箱材料需通过ISO75认证，并且需提交证书\r\n2.需提供表箱型式测试报告，测试机构需是IEC17025认可的实验室\r\n\r\n', '根据合作方式，决定银河还是代理开立保函\r\n保函金额预计8万美金', '建议投标', '国际业务二部', '盛燕', '2015-08-20', '盛燕 2015-08-20 11:43:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('1918', '{6241C22B-3BAE-463C-BA62-ECAA3A87A372}', '0', 'INHE-0051', '2014-03-17 09:13:06', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'PZ', null, 'The Kenya Power * Lighting Company Limited', '', '肯尼亚 ', '', 'Mary Mbacha 00 254 20 320 1336 ext 109\n00254 721 697472', '', 'K01和P01项目的合作代理 ', 'PZ', '03', '肯尼亚 ', '目前待确认投标代理，及投标合作方式。 \r\n1. 投标代理可选择William，或TAN客户，或其他，正在考察一些客户，最迟3月17日需确定下来。 \r\n2.关于合作方式，考虑到此市场付款条件苛刻，建议代理直接投标，我们提供CIF报价，做为厂家支持。 ', '智能电表集抄项目，需求产品为PLC集抄产品，含电表，集中器及软件。招标产品分为3个包，每个包需求产品数量和规格一样，最终分标为3家公司。 \r\n3月17日，召开标前会议 \r\n3月19日，智能电表安装现场考察 \r\n4月15日，截标 \r\n中标后，要求中标方去KPLC进行展示。 　\r\n', '肯尼亚市场一直使用简单后付费表和双绞线通讯的代码表，技术含量低，竞争激烈，利润低，现在的智能集抄试点项目，是我司占领市场的一个好时机。 ', '42109', '2', '', '', '', '', '', '1.关于代理选择和合作方式，希望公司领导提供意见。 \r\n2.此项目需技术支持，召开技术沟通会议，并需要如期准备样机，若有必要，前往现场考察，参加3月19日的现场考察活动　\r\n', '国际业务二部', '盛燕', '2014-03-17', '盛燕 2014-03-17 09:13:06', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
