INSERT INTO `crs_tabledata686` VALUES ('1946', '{6241C22B-3BAE-463C-BA62-ECAA3A87A400}', '0', 'INHE-0051', '2015-07-30 17:09:20', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ESM', null, 'Nyamezela Consulting Engineers (Pty) Ltd.', '', '南非', '', 'Nyamezela Consulting Engineers\r\n910 Almond Rock Avenue\r\nStrubens Valley Ext 4 1735, South Africa\r\nTel +27 11 675 7669 / 27 837022726 Fax 0866972822\r\nMrs Matsotso Vuso', '', '客户从事电力设备，建筑，咨询相关业务，和我们已合作ZEC2，ESA项目', 'ESM', '03', '南非', '1.代理直接参加投标，我们供应散件\r\n2.关于此项目合作代理（NYC或I4或ZAR01代理），待继续考察和沟通', '1.ESKOM招标项目，供货，交付和安装32885台智能预付费电能表，8月18日截标\r\n2.需求产品有单相表，三相表，集中器，AMI软件，电表安装，集中器安装，投标方可以投部分产品，但是必须提供一个完整的系统。ESKOM可以决定分标。\r\n3.资质要求：仅限南非本地承包商，B-BBEE等级1-4级，至少60%本地化\r\n4.评标规则：\r\n1）第一阶段：评估是否满足标书列出的技术门槛（强制性要求），若不满足直接出局\r\n2）第二阶段：截标日前，不需提交样机。通过第一阶段后，ESKOM将通知入选投标方准备样机，并且', 'ESKOM公开招标智能表，后续智能表需求会增加，此项目技术规格比较前沿，可推广到其他市场', '2014年8月8日', '截标日前不需要，后期需要，建议公司提前准备', '', '', '', '我们主要提供技术资料，此项目技术有难度，需技术支持协助评估，并且完成部分技术资料制作', '不需开立保函', '此项目需仔细研读技术规格，参加投标', '国际业务二部', '盛燕', '2015-07-31', '盛燕 2015-07-31 08:36:54', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
