INSERT INTO `crs_tabledata686` VALUES ('1956', '{6241C22B-3BAE-463C-BA62-ECAA3A87A410}', '0', 'INHE-0015', '2015-11-02 14:24:46', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'WZ', null, 'Ideal Enterprise', '', '孟加拉', '', 'A.K.Sarker\r\nIdeal Enterprise\r\n31 BB Avenue,\r\nDhaka 1000\r\nBangladesh\r\nTel: 00880 2 9551938/9569467\r\nFax: 00880 2 9561866\r\nMobile: 00880 1711522675\r\n         00880 1711535660 (for messaging)\r\nEmail: sarkerak@gmail.com\r\nSkype ID: sarkerak\r\n\r\n\r\n', '', '当地总包公司，曾经和海兴合作中标并执行第一个预付费交钥匙工程项目，在总包工程投标及执行方面有丰富的经验；', 'WZ', '03', '孟加拉', '客户作为投标人投标，开具投标保函，我司负责提供预付费电表产品报价并交货，我司与客户结算方式为即期信用证；', '该国电力部拟将全国产品换装为预付费产品，此标为预付费电表换表计划的一部分，之前曾经进行过招标，由于技术规格变更的原因重新招标，此次招标即为重新招标；', '', '2015.11.11', '单相、三相各两台', '稳定', '规范', '', '商务资料和文件准备可以在11月9日之前完成', '客户开立', '', '国际业务一部', '王维', '2015-11-02', '王维 2015-11-02 14:24:47', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
