INSERT INTO `crs_tabledata686` VALUES ('28511', '{6241C22B-3BAE-463C-BA62-ECAA3A87A428}', '61', 'INHE-0091', '2015-12-28 09:12:42', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'MD项目 立项申请表（v3.0流程（2015年12月28日08:53）林丽璇', null, 'Lucky Exports', '', '印度', '', 'Rohit Mittal\r\nManager - Lucky Exports,\r\nLogix Technopark, Ground Floor, Tower - C,\r\nPlot - 5, Sector 127, Noida, Uttar Pradesh\r\nPh.: +91-0120-4745200/01\r\nMob.: +91-9958756609/+91-9910074341\r\nSkype: angeleyes_rohit\r\nEmail: rohit@luckyexpindia.com\r\nWeb: www', '', '印度公司，在中东、非洲及独联体国家做进出口银行及其他金融机构下的各种项目，包括工程承包。', 'MD', '03', '马拉维', '招投标', '马拉维电力公司ESCOM的ESSP(energy sector support project)项目扩建33kV和11kV配电线路，招标产品有多种电缆，电表和四表位表箱是部分需求。', '', '1、DIN导轨安装单相二线分体式（PLC载波通信）代码智能电表技术规格同M11项目技术规格，要求底部接线，IP54。\r\n2、单相DIN四表位表箱要求3个母线排：火线排、零线排、地线排；表箱既可上铅封又可上锁。', '无', '', '良好', '良好', '可准时提供。', '代理投标，由代理开保函。', '虽然DIN表要求底部接线，建议按满足应答，用DINIII投标。', '国际业务二部', '林丽璇(Elle Lin)', '2015-12-28', '林丽璇 2015-12-28 10:54:48', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('28512', '{6241C22B-3BAE-463C-BA62-ECAA3A87A429}', '61', 'INHE-0091', '2015-12-28 09:12:42', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'MD项目 立项申请表（v3.0流程（2015年12月28日08:53）林丽璇', null, 'Lucky Exports', '', '印度', '', 'Rohit Mittal\r\nManager - Lucky Exports,\r\nLogix Technopark, Ground Floor, Tower - C,\r\nPlot - 5, Sector 127, Noida, Uttar Pradesh\r\nPh.: +91-0120-4745200/01\r\nMob.: +91-9958756609/+91-9910074341\r\nSkype: angeleyes_rohit\r\nEmail: rohit@luckyexpindia.com\r\nWeb: www', '', '印度公司，在中东、非洲及独联体国家做进出口银行及其他金融机构下的各种项目，包括工程承包。', 'MD', '03', '马拉维', '招投标', '马拉维电力公司ESCOM的ESSP(energy sector support project)项目扩建33kV和11kV配电线路，招标产品有多种电缆，电表和四表位表箱是部分需求。', '', '1、DIN导轨安装单相二线分体式（PLC载波通信）代码智能电表技术规格同M11项目技术规格，要求底部接线，IP54。\r\n2、单相DIN四表位表箱要求3个母线排：火线排、零线排、地线排；表箱既可上铅封又可上锁。', '无', '', '良好', '良好', '可准时提供。', '代理投标，由代理开保函。', '虽然DIN表要求底部接线，建议按满足应答，用DINIII投标。', '国际业务二部', '林丽璇(Elle Lin)', '2015-12-28', '林丽璇 2015-12-28 10:54:48', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('28513', '{E241C22B-3BAE-463C-BA62-FCAA3A87A001}', '61', 'INHE-0091', '2012-08-20 09:18:10', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'TAN', null, 'INTERTRADE COMMERCIAL SERVICES (P) LIMITED', '', '坦桑尼亚', 'Emmanuel', '91 22 26821640/ 1/ 2', '', '', 'TAN', '03', '坦桑尼亚', '由代理开保函，以代理公司名义投标。我司给代理报FOB价，代理报最终DAP Kurasini Central Store.', '由代理开保函，以代理公司名义投标。我司给代理报FOB价，代理报最终DAP Kurasini Central Store.', '此标共有12个Lot，Lo1至Lot4的电表技术规格是一样的（单相DIN导轨载波电能表），区别是表箱表位不同；Lot5的产品需求是带有集抄功能的三相分体式载波预付费电表及表箱；LOT6为CT AMR电表(CLASS 1)。LOT7为CT连接电表(CLASS 0.5).Lot8至Lot12为中高压计量箱（metering cabinet）。结合我司现有产品和每个LOT的招标数量，建议投LOT1至LOT5。此标是以季度供货。', '2012年9月14日', '', '', '良好', '良好', '商务资料制作基本上没什么大问题，主要是样机和表箱能否及时制作出来。', '因标书技术规格要求相对复杂，建议在未收到代理一样机全款之前安排样机制作及表箱采购。不知是否情况允许为此项目准备两套样机和表箱？', '', '国际业务二部', '林丽璇(Elle Lin)', '2012-08-20', '林丽璇 2012-08-20 16:57:33', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('28514', '{E241C22B-3BAE-463C-BA62-FCAA3A87A002}', '61', 'INHE-0091', '2012-08-20 09:18:10', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '2', 'TAN', null, 'INTERTRADE COMMERCIAL SERVICES (P) LIMITED', '', '坦桑尼亚', 'Emmanuel', '91 22 26821640/ 1/ 2', '', '', 'TAN', '03', '坦桑尼亚', '由代理开保函，以代理公司名义投标。我司给代理报FOB价，代理报最终DAP Kurasini Central Store.', '由代理开保函，以代理公司名义投标。我司给代理报FOB价，代理报最终DAP Kurasini Central Store.', '此标共有12个Lot，Lo1至Lot4的电表技术规格是一样的（单相DIN导轨载波电能表），区别是表箱表位不同；Lot5的产品需求是带有集抄功能的三相分体式载波预付费电表及表箱；LOT6为CT AMR电表(CLASS 1)。LOT7为CT连接电表(CLASS 0.5).Lot8至Lot12为中高压计量箱（metering cabinet）。结合我司现有产品和每个LOT的招标数量，建议投LOT1至LOT5。此标是以季度供货。', '2012年9月14日', '', '', '良好', '良好', '商务资料制作基本上没什么大问题，主要是样机和表箱能否及时制作出来。', '因标书技术规格要求相对复杂，建议在未收到代理一样机全款之前安排样机制作及表箱采购。不知是否情况允许为此项目准备两套样机和表箱？', '', '国际业务二部', '林丽璇(Elle Lin)', '2012-08-20', '林丽璇 2012-08-20 16:57:33', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
