INSERT INTO `crs_tabledata686` VALUES ('28518', '{E241C22B-3BAE-463C-BA62-FCAA3A87A006}', '61', 'INHE-0091', '2014-11-10 10:36:57', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'M108', null, 'TANESCO', '', '坦桑尼亚', '', 'Tanzania Electric Supply Company Limited \r\nTelephone: 255 22 2451130/41 \r\nTelefax:255 22 2451145/2452172', '', '该客户是坦桑尼亚电力公司，负责坦桑尼亚全国的发电，输电和配电工作。', 'M108', '03', '坦桑尼亚', '由TAN代理理公司名义投标，我方作为厂商提供技术支持。', '由TAN代理理公司名义投标，我方作为厂商提供技术支持。', '', '2014/11/28', '', '良好', '良好', '良好', '资料准备没有问题，样机需要紧急提供，最迟11月17日需寄出。', '代理投标，由代理负责开立', '', '国际业务二部', '林丽璇(Elle Lin)', '2014-11-10', '林丽璇 2014-11-10 11:03:57', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('28519', '{E241C22B-3BAE-463C-BA62-FCAA3A87A007}', '61', 'INHE-0091', '2014-11-10 10:36:57', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '2', 'M108', null, 'TANESCO', '', '坦桑尼亚', '', 'Tanzania Electric Supply Company Limited \r\nTelephone: 255 22 2451130/41 \r\nTelefax:255 22 2451145/2452172', '', '该客户是坦桑尼亚电力公司，负责坦桑尼亚全国的发电，输电和配电工作。', 'M108', '03', '坦桑尼亚', '由TAN代理理公司名义投标，我方作为厂商提供技术支持。', '由TAN代理理公司名义投标，我方作为厂商提供技术支持。', '', '2014/11/28', '', '良好', '良好', '良好', '资料准备没有问题，样机需要紧急提供，最迟11月17日需寄出。', '代理投标，由代理负责开立', '', '国际业务二部', '林丽璇(Elle Lin)', '2014-11-10', '林丽璇 2014-11-10 11:03:57', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('28520', '{E241C22B-3BAE-463C-BA62-FCAA3A87A008}', '61', 'INHE-0051', '2014-06-11 18:04:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'M10', null, 'ESCOM', '', '马拉维', '', '联系人：Wifred 采购经理\r\n电话：2651822000\r\n邮箱：WMPISA@ESCOM.MV', '', '马拉维电力公司负责全国发电输电配电', 'M10', '03', '马拉维', '和GMA合作投标，对投标方无明确限制，无需开立投标保函。投标合作方式待确认，最好银河直接投标。\r\n\r\n付款条件为LC,LC具体类型未明确。', '和GMA合作投标，对投标方无明确限制，无需开立投标保函。投标合作方式待确认，最好银河直接投标。\r\n\r\n付款条件为LC,LC具体类型未明确。', '1）马拉维电力公司直接招标，招标方式是局限性招标，备选公司有ITRON,CONLOG,ACTOM,L&G,银河，SEIFEL（法国一家能源通讯公司）。\r\n2）3个包，LOT1为PLC分体电表，LOT2为CT接入式最大需量表，LOT3为表箱，3个包分开评标。需求数量有15%浮动。\r\n3）对本地生产的电表，评估时有20%本地保护；评标主要考虑技术满足程度，报价，交期。\r\n4）此项目对交期要求严格，PLC分体表要求从合同日起6-12周交货到布兰太尔，海运周期为50-60天，生产周期非常短，最多34天。LOT2的', '2016/7/8', '', '', '', '', '表箱相关资料需技术支持协助提供', '不需开立投标保函', '', '国际业务二部', '盛燕', '2014-06-11', '盛燕 2014-06-11 18:43:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata686` VALUES ('28521', '{E241C22B-3BAE-463C-BA62-FCAA3A87A009}', '61', 'INHE-0051', '2014-06-11 18:04:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '2', 'M10', null, 'ESCOM', '', '马拉维', '', '联系人：Wifred 采购经理\r\n电话：2651822000\r\n邮箱：WMPISA@ESCOM.MV', '', '马拉维电力公司负责全国发电输电配电', 'M10', '03', '马拉维', '和GMA合作投标，对投标方无明确限制，无需开立投标保函。投标合作方式待确认，最好银河直接投标。\r\n\r\n付款条件为LC,LC具体类型未明确。', '和GMA合作投标，对投标方无明确限制，无需开立投标保函。投标合作方式待确认，最好银河直接投标。\r\n\r\n付款条件为LC,LC具体类型未明确。', '1）马拉维电力公司直接招标，招标方式是局限性招标，备选公司有ITRON,CONLOG,ACTOM,L&G,银河，SEIFEL（法国一家能源通讯公司）。\r\n2）3个包，LOT1为PLC分体电表，LOT2为CT接入式最大需量表，LOT3为表箱，3个包分开评标。需求数量有15%浮动。\r\n3）对本地生产的电表，评估时有20%本地保护；评标主要考虑技术满足程度，报价，交期。\r\n4）此项目对交期要求严格，PLC分体表要求从合同日起6-12周交货到布兰太尔，海运周期为50-60天，生产周期非常短，最多34天。LOT2的', '2016/7/8', '', '', '', '', '表箱相关资料需技术支持协助提供', '不需开立投标保函', '', '国际业务二部', '盛燕', '2014-06-11', '盛燕 2014-06-11 18:43:44', '', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
